// session-hub: the session bar above every prompt with its two chips (☐ open
// to-dos, ⚠ work not committed), the to-do list in one chat, and the commit
// guard. This file only wires events to the parts.

import { atom, read } from 'claude-code'
import type { EngineInterface, Register, ResolveInput } from 'claude-code'

import type { HubTodo } from '../types'
import { openList, runDirty, runTodo } from './commands'
import { planCommit, settleCommit } from './commits'
import { checkEdits, resetEdits, trackEdit } from './edits'
import { tickRepos, tickStore } from './home'
import { cancelTimers, hub, isIgnoredRepo, resetHub } from './hub'
import { callFacts } from './lib/git'
import { listModel } from './lib/list'
import { readOptions } from './lib/options'
import { DESKTOP, isPersonChat } from './lib/registry'
import { openTarget } from './sources/open'
import { findPlace } from './sources/place'
import { readRegistry } from './sources/sessions'
import { flushRev, loadNow, step } from './store-sync'
import { markDone, snooze, tickSessions } from './todos'
import { drawBar } from './ui/bar'
import { drawList } from './ui/list'

const SCAN_MS = 3000
const STORE_MS = 10000
const REPOS_MS = 5 * 60 * 1000

// Atoms are declared in each file that reads or writes them (the engine
// reads them off the source); these are read while drawing, so a change
// redraws the bar, the list and the pane. hub.ts declares the same ones for writing.
const rowsAtom = atom({ plugin: 'session-hub', key: 'rows' } as const, [])
const nowAtom = atom({ plugin: 'session-hub', key: 'now' } as const, 0)
const limitsAtom = atom({ plugin: 'session-hub', key: 'limits' } as const, [])
const todosAtom = atom({ plugin: 'session-hub', key: 'todos' } as const, [])
const reposAtom = atom({ plugin: 'session-hub', key: 'repos' } as const, [])
const reposAtAtom = atom({ plugin: 'session-hub', key: 'reposAt' } as const, 0)
const isHomeAtom = atom({ plugin: 'session-hub', key: 'isHome' } as const, false)

const TODO_HELP = 'The to-do list: add an item, list them, or show the list here (here|off)'
const DIRTY_HELP = 'Repos with uncommitted or unpushed work'

// A name the engine refuses (a built-in's) falls back to its hub- twin.
async function registerCommands($: EngineInterface) {
  await $.command.register({ name: 'todo', description: TODO_HELP, argumentHint: '[text|here|off]' })
    .catch(() => $.command.register({ name: 'hub-todo', description: TODO_HELP, argumentHint: '[text|here|off]' }))
    .catch(() => undefined)
  await $.command.register({ name: 'dirty', description: DIRTY_HELP })
    .catch(() => $.command.register({ name: 'hub-dirty', description: DIRTY_HELP }))
    .catch(() => undefined)
}

// What the start waits for: the commands, so they exist for the first turn.
// Everything else runs from a timer, off the path of the first prompt.
//
// A person's chat (a terminal REPL, or a desktop chat: its process is
// headless, but its own registry entry is an interactive one with a desktop
// id) reads, settles and polls. A `-p` or SDK run keeps only the commit guard
// and the turn-end edit record; so does a `claude -p` started from a desktop
// chat's shell (the desktop entrypoint, no desktop id). The desktop may write
// the entry, or its id, a moment after the start, so a non-interactive start
// looks a few times before it decides.
const SELF_TRIES = 6
const SELF_RETRY_MS = 5000

async function boot($: EngineInterface, isInteractive: boolean, attempt: number) {
  hub.place ??= await findPlace($)
  const place = hub.place
  if (place === null) return
  place.selfId = await $.session.id()
  const self = (await readRegistry($, place, hub.sessions).catch(() => []))
    .find(entry => entry.sessionId === place.selfId)
  const isKnown = self !== undefined && (self.entrypoint !== DESKTOP || self.hostSessionId !== undefined)
  if (!isInteractive && !isKnown && attempt < SELF_TRIES) {
    hub.timers.push($.clock.after(SELF_RETRY_MS, () => void boot($, isInteractive, attempt + 1).catch(() => undefined)))

    return
  }
  hub.isPerson = isInteractive || isPersonChat(self)
  await isIgnoredRepo($, '')
  if (!hub.isPerson) return
  // The stored items first, so the first detection writes nothing it has;
  // then sessions, so this chat knows its own desktop id before the home.
  await step($, 'store', () => loadNow($))
  await step($, 'sessions', () => tickSessions($))
  await step($, 'store', () => tickStore($))
  hub.timers.push($.clock.every(SCAN_MS, () => void step($, 'sessions', () => tickSessions($))))
  hub.timers.push($.clock.every(STORE_MS, () => void step($, 'store', () => tickStore($))))
  if (hub.options.commitGuard) hub.timers.push($.clock.every(REPOS_MS, () => void step($, 'repos', () => tickRepos($))))
}

const counts = (todos: readonly HubTodo[]) => ({ todo: todos.length, risk: todos.filter(todo => todo.isRisk).length })

function actions($: EngineInterface) {
  const isWindows = hub.place?.isWindows ?? true
  const saved = (work: Promise<void>) => void work.catch(() => $.ui.toast('Could not save'))

  return {
    openSession: (link: string) => void openTarget($, link, isWindows),
    openList: () => void openList($, isWindows),
    done: (todo: HubTodo) => saved(markDone($, todo)),
    snooze: (todo: HubTodo) => saved(snooze($, todo)),
  }
}

async function drawListFromState($: EngineInterface, e: ResolveInput) {
  const model = listModel({
    todos: await read($, todosAtom),
    repos: await read($, reposAtom),
    reposAt: await read($, reposAtAtom),
    now: await read($, nowAtom),
  })

  return drawList($, e, model, actions($))
}

export const register: Register = (on, options) => {
  resetHub(readOptions(options))
  resetEdits()

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    cancelTimers()
    await registerCommands($).catch(() => undefined)
    hub.timers.push($.clock.after(0, () => void boot($, e.isInteractive, 1).catch(() => undefined)))

    return started
  })

  // The edit check runs from a timer, off the turn's path.
  on('turn.complete', async ($, e, next) => {
    const completed = await next(e)
    if (e.agentId === undefined && hub.options.commitGuard) {
      $.clock.after(0, () => void step($, 'edits', () => checkEdits($)))
    }

    return completed
  }).catch(($, e, next) => next(e))

  // Observes only: always hands back what the tool returned, at once. Before
  // the command it reads HEAD from the .git files; the verdict comes later.
  on('tool.call', { tool: ['Bash', 'PowerShell'] }, async ($, e, next) => {
    const plan = hub.options.commitGuard ? await planCommit($, e).catch(() => null) : null
    const ran = await next(e)
    if (plan !== null) {
      const facts = callFacts(ran, e)
      $.clock.after(0, () => void settleCommit($, plan, facts).catch(() => undefined).then(() => flushRev($)).catch(() => undefined))
    }

    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: ['Edit', 'Write', 'NotebookEdit'] }, async ($, e, next) => {
    const ran = await next(e)
    if (hub.options.commitGuard && ran.deny === undefined && ran.isError !== true) {
      trackEdit(e.tool === 'NotebookEdit' ? e.notebook_path : e.file_path, await $.clock.now())
    }

    return ran
  }).catch(($, e, next) => next(e))

  on('command.run', { command: ['todo', 'hub-todo'] }, ($, e) => runTodo($, e.args))
    .catch(() => ({ text: 'Could not read the to-do list. Try again.' }))
  on('command.run', { command: ['dirty', 'hub-dirty'] }, $ => runDirty($))
    .catch(() => ({ text: 'Could not read the repos. Try again.' }))

  // The list chat shows the list; every other chat the bar, or nothing.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    if (await read($, isHomeAtom)) return drawListFromState($, e)
    const rows = await read($, rowsAtom)
    const limits = await read($, limitsAtom)
    const { todo, risk } = counts(await read($, todosAtom))
    if (rows.length === 0 && limits.length === 0 && todo === 0) return next(e)

    return drawBar($, e, { rows, todo, risk, limits, now: await read($, nowAtom) }, actions($))
  })

  // The list as a pane: the id is commands.ts LIST_PANE, spelled here so the engine reads it off the source.
  on('ui.render', { component: 'Pane', requestId: 'todo' }, ($, e) => drawListFromState($, e))
}

