// /todo and /dirty. `/todo here` makes this chat show the to-do list above
// the prompt, `/todo off` stops it, `/todo` answers the list as text, and
// `/todo <text>` adds an item.

import type { EngineInterface } from 'claude-code'

import { listChatLink, refreshRepos, setHome } from './home'
import { hub, openItems, publish } from './hub'
import { isHomeAlive } from './lib/home'
import { dirtyText, listModel, listText } from './lib/list'
import { manualItem } from './lib/todo'
import { openTarget } from './sources/open'
import { loadHome } from './sources/store'
import { flushRev, loadNow } from './store-sync'
import { addItem } from './todos'

export const LIST_PANE = 'todo'

const countsText = () => {
  const todos = hub.view.todos
  const risk = todos.filter(todo => todo.isRisk).length

  return [`☐ ${todos.length}`, risk > 0 ? `⚠ ${risk}` : null].filter(Boolean).join(' · ')
}

// From the ☐ and ⚠ chips: the running chat that shows the list, else the
// list as a pane; a pane the surface will not place shows the counts instead.
export async function openList($: EngineInterface, isWindows: boolean) {
  const link = listChatLink()
  if (link !== null) {
    await openTarget($, link, isWindows)

    return
  }
  const opened = await $.ui.open({ id: LIST_PANE, title: 'To do' }).catch(() => null)
  if (opened === null || !opened.isPlaced) $.ui.toast(countsText())
}

// The list as the store has it now (a `-p` run never loads otherwise); with
// no running list chat anywhere, the repo scan runs on demand.
async function currentList($: EngineInterface, now: number) {
  await loadNow($)
  const home = await loadHome($).catch(() => null)
  if (!isHomeAlive(home, hub.liveIds) && hub.options.commitGuard) await refreshRepos($).catch(() => undefined)
  await flushRev($).catch(() => undefined)
  await publish($, { todos: openItems(now) })

  return listModel({ todos: hub.view.todos, repos: hub.view.repos, reposAt: hub.view.reposAt, now })
}

export async function runTodo($: EngineInterface, args: string) {
  const text = args.trim()
  const word = text.toLowerCase()
  if (word === 'here') {
    await setHome($, true)
    if (hub.options.commitGuard) await refreshRepos($).catch(() => undefined)
    await flushRev($).catch(() => undefined)

    return { text: 'To-do list: this chat' }
  }
  if (word === 'off') {
    await setHome($, false)

    return { text: 'To-do list: no chat' }
  }
  if (!hub.options.todo) return { text: 'To-do list is off' }
  const now = await $.clock.now()
  if (text === '') return { text: listText(await currentList($, now)) }
  const item = manualItem(text, now, Math.random().toString(36).slice(2, 8))
  await addItem($, item, now)
  await flushRev($)

  return { text: `☐ ${item.title}` }
}

export async function runDirty($: EngineInterface) {
  if (!hub.options.commitGuard) return { text: 'Commit guard is off' }
  await refreshRepos($).catch(() => undefined)
  await flushRev($).catch(() => undefined)

  return { text: dirtyText(hub.view.repos, await $.clock.now()) }
}

