// Commit verification around a Bash or PowerShell call that runs `git commit`.
// Before the command: HEAD from the .git files (no git process). After it,
// off the tool's path: the engine's own commit record, or HEAD again. It only
// observes; anything it cannot resolve gets no verdict at all.

import type { EngineInterface } from 'claude-code'

import { hub, linkOfSelf } from './hub'
import { readableHead } from './lib/checks'
import { commitDir, commitOutcome, findCommit } from './lib/git'
import type { CallFacts } from './lib/git'
import type { GitDirs, Head } from './lib/gitfs'
import { basename, repoKey } from './lib/paths'
import { commitFailed, commitLanded } from './repo-checks'
import { findRepo, headOf } from './sources/gitfs'
import { putPending } from './store-sync'

// Claude often fails, fixes and retries in one turn: one toast per repo per
// 10 minutes; the item carries every attempt.
const TOAST_GAP_MS = 10 * 60 * 1000

// `ref`: the branch the commit is judged on (a `checkout -b` names a new one).
export type CommitPlan = { dirs: GitDirs; before: Head; ref: string | null; movesHead: boolean }

type ShellCall = { command: string }

// A folder spelled through a variable, `~` or a popd, or a git dir with no
// work tree, is unknown; so is a reftable repo: no verdict.
export async function planCommit($: EngineInterface, e: ShellCall): Promise<CommitPlan | null> {
  const call = findCommit(e.command)
  if (call === null || !call.isDirKnown) return null
  const dirs = await findRepo($, commitDir(await $.session.cwd(), call), hub.realPaths)
  if (dirs === null) return null
  const head = await headOf($, dirs)
  if (head === null) return null

  return {
    dirs,
    before: head,
    ref: call.newBranch === null ? head.ref : `refs/heads/${call.newBranch}`,
    movesHead: call.movesHead,
  }
}

function toastFailure($: EngineInterface, repo: string, detail: string | null, at: number) {
  const key = repoKey(repo)
  if (at - (hub.toastAt.get(key) ?? Number.NEGATIVE_INFINITY) < TOAST_GAP_MS) return
  hub.toastAt.set(key, at)
  const name = basename(repo)
  $.ui.toast(detail === null ? `Commit did not land · ${name}` : `Commit did not land · ${name}\n${detail}`)
}

// The engine's record wins. Otherwise HEAD decides, and only on the branch the
// commit runs on, in a command that moved HEAD no other way; a refusal or an
// interruption counts only when HEAD did not move.
export async function settleCommit($: EngineInterface, plan: CommitPlan, facts: CallFacts) {
  if (facts.isDenied) return
  const repo = plan.dirs.root
  const at = await $.clock.now()
  if (facts.engineCommit !== null) {
    await commitLanded($, repo, at)

    return
  }
  if (plan.movesHead) return
  // Still running: any chat settles it from the files later; no toast now.
  if (facts.isBackgrounded) {
    await putPending($, { repo, headBefore: plan.before.sha, refBefore: plan.ref, startedAt: at })

    return
  }
  const after = readableHead(plan.before.sha, await headOf($, plan.dirs))
  if (after === null || after.ref !== plan.ref) return
  if (after.sha !== plan.before.sha) {
    await commitLanded($, repo, at)

    return
  }
  if (facts.isRefused || facts.isInterrupted) return
  const { verdict, detail } = commitOutcome(plan.before.sha, after.sha, facts.output)
  if (verdict !== 'failed') return
  toastFailure($, repo, detail, at)
  await commitFailed($, repo, at, detail, linkOfSelf(), after)
}

files.hooks/edits.ts:
// Session edits: paths this session's Edit, Write and NotebookEdit calls
// changed, with when. At the end of a turn, the repos where some are still
// uncommitted get a dirty check in $.store; any chat settles it 10 minutes
// later (lib/checks.ts, repo-checks.ts), even after this chat has closed.
// Each path is kept as the file's real path inside the repo's real root, so a
// file edited through a junction, or spelled in another letter case, is the
// file git knows.

import type { EngineInterface } from 'claude-code'

import { hub, isIgnoredRepo, linkOfSelf } from './hub'
import { dirtyCheckId, mergeCheck } from './lib/checks'
import { basename, joinPath, repoKey } from './lib/paths'
import { askDirtyFiles } from './repo-checks'
import { findRepo, realPathOf } from './sources/gitfs'
import { loadCheck } from './sources/store'
import { putCheck } from './store-sync'

const edits = {
  // Path → when this session last changed it.
  paths: new Map<string, number>(),
  // Folder → its real path and repo root (null: not in a repo, as of `at`;
  // an edit made after that is looked at again, as after a `git init`).
  folders: new Map<string, { real: string; repo: string | null; at: number }>(),
}

export const resetEdits = () => {
  Object.assign(edits, { paths: new Map(), folders: new Map() })
}

export const trackEdit = (path: string, at: number) => {
  if (path !== '' && hub.options.todo) edits.paths.set(path, at)
}

const folderOf = (path: string) => path.replace(/[\\/][^\\/]*$/, '') || path

async function folderInfo($: EngineInterface, folder: string, editedAt: number, at: number) {
  const known = edits.folders.get(folder)
  if (known !== undefined && (known.repo !== null || known.at >= editedAt)) return known
  const real = await realPathOf($, folder, hub.realPaths)
  const info = { real, repo: (await findRepo($, real, hub.realPaths))?.root ?? null, at }
  edits.folders.set(folder, info)

  return info
}

// The file's own real path (its letter case on disk), else its folder's.
async function realFile($: EngineInterface, path: string, folder: string) {
  const stat = await $.fs.stat(path, { resolve: true }).catch(() => null)

  return stat?.realPath ?? joinPath(folder, basename(path))
}

type Group = { repo: string; paths: string[]; spelled: string[]; lastEditAt: number }

async function groupByRepo($: EngineInterface, at: number) {
  const groups = new Map<string, Group>()
  for (const [path, editedAt] of edits.paths) {
    const { real, repo } = await folderInfo($, folderOf(path), editedAt, at)
    if (repo === null) {
      edits.paths.delete(path)
      continue
    }
    const group = groups.get(repoKey(repo)) ?? { repo, paths: [], spelled: [], lastEditAt: 0 }
    group.paths.push(await realFile($, path, real))
    group.spelled.push(path)
    group.lastEditAt = Math.max(group.lastEditAt, editedAt)
    groups.set(repoKey(repo), group)
  }

  return groups
}

// Run off the turn's path, from a timer the turn.complete hook sets. git is
// asked through the one routine (which also cuts down the repo's dirty item);
// the check takes the files still uncommitted, merged with the stored check
// read fresh. A repo git cannot answer for still gets its check, which backs
// off and gives up only after a day. Ignored repos get none.
export async function checkEdits($: EngineInterface) {
  if (edits.paths.size === 0 || !hub.options.todo) return
  const at = await $.clock.now()
  const owner = hub.place?.selfId ?? (await $.session.id())
  for (const group of (await groupByRepo($, at)).values()) {
    for (const path of group.spelled) edits.paths.delete(path)
    if (await isIgnoredRepo($, group.repo)) continue
    const dirty = await askDirtyFiles($, group.repo, group.paths)
    const isDirty = new Set((dirty ?? []).map(path => path.toLowerCase()))
    const paths = dirty === null ? group.paths : group.paths.filter(path => isDirty.has(path.toLowerCase()))
    if (paths.length === 0) continue
    const id = dirtyCheckId(group.repo)
    const link = linkOfSelf()
    const next = { repo: group.repo, paths, lastEditAt: group.lastEditAt, at, owner, ...(link === null ? {} : { link }) }
    const stored = (await loadCheck($, id).catch(() => null)) ?? hub.checks.get(id)
    await putCheck($, id, mergeCheck(stored, next))
  }
}

