// The list chat (the home: the chat that shows the to-do list), the repo
// scan, and the store tick that settles what any person's chat may settle.

import type { EngineInterface } from 'claude-code'

import { hub, isIgnoredRepo, openItems, publish } from './hub'
import { isHomeAlive, isHomeChat } from './lib/home'
import type { Home } from './lib/home'
import { expandHome, repoKey } from './lib/paths'
import { linkOf } from './lib/sessions'
import { askDirtyFiles, CHECKS_AT_ONCE, settleChecks, settleCommitItems, settlePending } from './repo-checks'
import { pool } from './sources/git'
import { scanRepos } from './sources/repos'
import { findPlace } from './sources/place'
import { loadHome, loadScan, saveHome, saveScan } from './sources/store'
import { reloadIfMoved, step } from './store-sync'
import { prunePass } from './todos'

const SCAN_READ_MS = 60000

async function homePass($: EngineInterface, at: number) {
  const place = hub.place
  if (place === null) return
  const home = await loadHome($)
  const wasHome = hub.isHome
  hub.home = home
  hub.isHome = isHomeChat(home, place.selfId, hub.selfHost)
  // This chat is home under new ids (after /clear or a restart): record them.
  const self: Home = { sessionId: place.selfId, hostSessionId: hub.selfHost, pid: hub.selfPid }
  const isStale = home !== null && (home.sessionId !== self.sessionId ||
    home.hostSessionId !== self.hostSessionId || home.pid !== self.pid)
  if (hub.isHome && isStale && (self.hostSessionId !== null || home?.hostSessionId === null)) {
    await saveHome($, self, at)
    hub.home = self
  }
  await publish($, { isHome: hub.isHome })
  // Another chat's scan changes every 5 minutes: a look once a minute will do.
  if (!hub.isHome && at - hub.scanReadAt >= SCAN_READ_MS) {
    hub.scanReadAt = at
    const scan = await loadScan($)
    if (scan !== null) await publish($, { repos: scan.repos, reposAt: scan.at })
  }
  // Just became home, restarted as home, or made home before this chat's
  // start had run: scan now, not in 5 minutes.
  if (hub.isHome && (!wasHome || !hub.hasScanned) && hub.options.commitGuard) void step($, 'repos', () => refreshRepos($))
}

// Every 10 s in a person's chat. Commit items are read in the home chat only
// (elsewhere on demand, with the scan).
export async function tickStore($: EngineInterface) {
  const at = await $.clock.now()
  await reloadIfMoved($)
  await prunePass($, at)
  await homePass($, at)
  if (hub.options.commitGuard) {
    await settlePending($, at)
    if (hub.isHome) await settleCommitItems($)
    await settleChecks($, at)
  }
  await publish($, { todos: openItems(at) })
}

// The repo scan: in the home chat every 5 minutes, elsewhere on demand. It
// shows repos and saves the snapshot; for a repo holding a dirty item it
// asks git about that item's own files, and judges nothing from its listing.
// A headless run only shows.
export async function refreshRepos($: EngineInterface) {
  hub.place ??= await findPlace($)
  const place = hub.place
  if (place === null) return
  await isIgnoredRepo($, '')
  const itemRepos = [...hub.items.values()].flatMap(item => (item.repo === undefined ? [] : [item.repo]))
  const repos = await scanRepos($, {
    roots: hub.options.scanRoots.map(root => expandHome(root, place.home, place.sep)),
    extra: itemRepos,
    ignored: hub.ignored ?? new Set(),
    itemRepos: new Set(itemRepos.map(repoKey)),
    sep: place.sep,
    realPaths: hub.realPaths,
  })
  const at = await $.clock.now()
  await publish($, { repos, reposAt: at })
  if (!hub.isPerson) return
  await saveScan($, { at, repos }).catch(() => undefined)
  hub.hasScanned = true
  const dirty = [...hub.items.values()].flatMap(item => (item.kind === 'dirty' && item.repo !== undefined ? [item.repo] : []))
  await pool(dirty.map(repo => () => askDirtyFiles($, repo)), CHECKS_AT_ONCE)
  if (!hub.isHome) await settleCommitItems($)
  await publish($, { todos: openItems(at) })
}

export async function tickRepos($: EngineInterface) {
  if (hub.isHome) await refreshRepos($)
}

// /todo here (the last one wins) and /todo off.
export async function setHome($: EngineInterface, isOn: boolean) {
  const at = await $.clock.now()
  const sessionId = hub.place?.selfId ?? (await $.session.id())
  const home: Home = { sessionId, hostSessionId: hub.selfHost, pid: hub.selfPid }
  await saveHome($, isOn ? home : null, at)
  hub.home = isOn ? home : null
  hub.isHome = isOn
  await publish($, { isHome: isOn })
}

// The running chat that shows the list, when it is another one: its link.
export const listChatLink = () => {
  const home = hub.home
  if (hub.isHome || home === null || home.hostSessionId === null || !isHomeAlive(home, hub.liveIds)) return null

  return linkOf(home.hostSessionId)
}

