// The module's working memory and what $.state last received. A hot reload
// starts this over; the host's $.state and the plugin's $.store remain.
// The steps that keep it current: store-sync.ts (the store), todos.ts
// (sessions and to-dos), repo-checks.ts (git) and home.ts (home and scan).

import { atom, update } from 'claude-code'
import type { EngineInterface, PluginState, Timer } from 'claude-code'

import type { HubRow, HubTodo } from '../types'
import type { DirtyCheck, PendingCommit } from './lib/checks'
import type { Home } from './lib/home'
import type { Options } from './lib/options'
import { DEFAULTS } from './lib/options'
import { expandHome, repoKey } from './lib/paths'
import type { Facts, Finish } from './lib/sessions'
import { openTodos } from './lib/todo'
import type { TodoItem, TodoState } from './lib/todo'
import { realPathOf } from './sources/gitfs'
import { findPlace } from './sources/place'
import type { Place } from './sources/place'
import { newSessionCache } from './sources/sessions'
import { newUsageCache } from './sources/usage'

export type View = PluginState['session-hub']

const rowsAtom = atom({ plugin: 'session-hub', key: 'rows' } as const, [])
const nowAtom = atom({ plugin: 'session-hub', key: 'now' } as const, 0)
const limitsAtom = atom({ plugin: 'session-hub', key: 'limits' } as const, [])
const todosAtom = atom({ plugin: 'session-hub', key: 'todos' } as const, [])
const reposAtom = atom({ plugin: 'session-hub', key: 'repos' } as const, [])
const reposAtAtom = atom({ plugin: 'session-hub', key: 'reposAt' } as const, 0)
const isHomeAtom = atom({ plugin: 'session-hub', key: 'isHome' } as const, false)

// No revision is ever this: the first poll always loads.
export const NEVER_LOADED = '\u0000'

const emptyView = (): View => ({
  rows: [], now: 0, limits: [], todos: [], repos: [], reposAt: 0, isHome: false,
})

const fresh = (options: Options) => ({
  options,
  place: null as Place | null,
  selfHost: null as string | null,
  selfPid: null as number | null,
  isHome: false,
  // A person's chat (desktop or terminal) detects, settles and polls; a
  // headless or SDK run keeps only the commit guard and its edit record.
  isPerson: false,
  sessions: newSessionCache(),
  usage: newUsageCache(),
  // Spelling → real path; the ignore list as repoKeys of real paths.
  realPaths: new Map<string, string>(),
  ignored: null as Set<string> | null,
  items: new Map<string, TodoItem>(),
  states: new Map<string, TodoState>(),
  pending: new Map<string, PendingCommit>(),
  checks: new Map<string, DirtyCheck>(),
  facts: new Map<string, Facts>(),
  // The sessions the bar names.
  rows: [] as HubRow[],
  finishes: [] as Finish[],
  // Session ids and desktop ids of running sessions; ids of those in a turn.
  liveIds: new Set<string>(),
  busyIds: new Set<string>(),
  home: null as Home | null,
  // Store sync (store-sync.ts): the revision last loaded, or null while this
  // chat's landed writes owe the revision a bump; and its writes under way.
  seenRev: NEVER_LOADED as string | null,
  inFlight: 0,
  // When this chat last read another chat's repo scan; whether it saved one.
  scanReadAt: 0,
  hasScanned: false,
  // repoKey → when a failed commit there last raised a toast.
  toastAt: new Map<string, number>(),
  // What $.state last received, for the commands' text and change checks.
  view: emptyView(),
  written: new Map<string, string>(),
  running: new Set<string>(),
  timers: [] as Timer[],
})

export const hub = fresh(DEFAULTS)

export const cancelTimers = () => {
  for (const timer of hub.timers) timer.cancel()
  hub.timers = []
}

export const resetHub = (options: Options) => {
  cancelTimers()
  Object.assign(hub, fresh(options))
}

// Writes the changed values of `patch` to $.state; an unchanged value is
// skipped, so the drawings redraw only on a change.
export async function publish($: EngineInterface, patch: Partial<View>) {
  for (const [name, value] of Object.entries(patch)) {
    const json = JSON.stringify(value)
    if (hub.written.get(name) === json) continue
    switch (name) {
      case 'rows': await update($, rowsAtom, () => value as View['rows']); break
      case 'now': await update($, nowAtom, () => value as number); break
      case 'limits': await update($, limitsAtom, () => value as View['limits']); break
      case 'todos': await update($, todosAtom, () => value as View['todos']); break
      case 'repos': await update($, reposAtom, () => value as View['repos']); break
      case 'reposAt': await update($, reposAtAtom, () => value as number); break
      case 'isHome': await update($, isHomeAtom, () => value as boolean); break
      default: continue
    }
    hub.written.set(name, json)
    hub.view = { ...hub.view, [name]: value }
  }
}

export const openItems = (at: number): HubTodo[] => (hub.options.todo ? openTodos(hub.items, hub.states, at) : [])

export const linkOfSelf = () => (hub.selfHost === null ? null : `claude://claude.ai/epitaxy/${hub.selfHost}`)

// The ignore list's real paths (`~` is the home folder), resolved once.
export async function isIgnoredRepo($: EngineInterface, repo: string) {
  if (hub.ignored === null) {
    hub.place ??= await findPlace($)
    const home = hub.place?.home ?? null
    const sep = hub.place?.sep ?? '/'
    const keys = new Set<string>()
    for (const path of hub.options.ignoreRepos) {
      keys.add(repoKey(await realPathOf($, expandHome(path, home, sep), hub.realPaths)))
    }
    hub.ignored = keys
  }

  return hub.ignored.has(repoKey(repo))
}

