// Reading git commits out of Bash and PowerShell command lines, reading a
// tool result's facts, and deciding whether a commit landed. No processes:
// the adapters read HEAD and pass the results in.

import { joinPath } from './paths'

export type CommitCall = {
  // cd / Set-Location / Push-Location targets and -C dirs, in the order they apply.
  dirs: string[]
  isAmend: boolean
  // False when a target is a variable, `~`, `-`, missing, or a popd: the
  // folder the commit ran in is then unknown, and nothing is judged.
  isDirKnown: boolean
  // The command also checks out, resets, pulls...: a moved HEAD proves nothing.
  movesHead: boolean
  // `checkout -b <name>` / `switch -c <name>` (no start point) before the
  // commit: a new branch at the same commit, where the commit is then judged.
  newBranch: string | null
}

export type CommitVerdict = 'landed' | 'nothing' | 'failed'

const SEPARATORS = new Set([';', '|', '&', '\n', '{', '}'])

// Splits on && || ; | & braces and newlines that stand outside quotes, so a
// PowerShell `if ($?) { git commit }` block is a segment of its own.
const segments = (command: string) => {
  const found: string[] = []
  let current = ''
  let quote: '"' | "'" | null = null
  for (let i = 0; i < command.length; i += 1) {
    const char = command[i]!
    if (quote !== null) {
      current += char
      if (char === quote) quote = null
      continue
    }
    if (char === '"' || char === "'") {
      quote = char
      current += char
      continue
    }
    if (SEPARATORS.has(char)) {
      found.push(current)
      current = ''
      if ((char === '&' || char === '|') && command[i + 1] === char) i += 1
      continue
    }
    current += char
  }
  found.push(current)

  return found
}

// Words of one segment, quotes removed; a quoted part never splits.
const words = (segment: string) => {
  const list: string[] = []
  let current = ''
  let hasWord = false
  let quote: '"' | "'" | null = null
  for (const char of segment) {
    if (quote !== null) {
      if (char === quote) quote = null
      else current += char
      continue
    }
    if (char === '"' || char === "'") {
      quote = char
      hasWord = true
      continue
    }
    if (/\s/.test(char)) {
      if (hasWord) list.push(current)
      current = ''
      hasWord = false
      continue
    }
    current += char
    hasWord = true
  }
  if (hasWord) list.push(current)

  return list
}

const CD = new Set(['cd', 'chdir', 'pushd', 'set-location', 'sl', 'push-location'])
const POP = new Set(['popd', 'pop-location'])
const CD_FLAGS = new Set(['-path', '-literalpath', '/d', '-l', '-p', '--'])
// Words that may stand before the command itself.
const LEADING = new Set(['&', '!', 'if', 'then', 'else', 'elif', 'do', 'while', 'until', 'time', 'command', 'exec'])
const GIT = /(^|[\\/])git(\.exe)?$/i
const ENV_ASSIGNMENT = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/
// A target spelled through a variable, the home folder or the previous folder.
const UNRESOLVABLE = /[$%`]|^~|^-$/

// The command's words, after leading keywords and VAR=value prefixes, and
// those prefixes (GIT_DIR and GIT_WORK_TREE name another repo).
const commandWords = (segment: string) => {
  const list = words(segment.replace(/^\s*[({]+/, '').replace(/[)}]+\s*$/, ''))
  const env = new Map<string, string>()
  while (list.length > 0) {
    const first = list[0]!
    const assignment = ENV_ASSIGNMENT.exec(first)
    if (assignment !== null) env.set(assignment[1]!, assignment[2]!)
    else if (!LEADING.has(first.toLowerCase())) break
    list.shift()
  }

  return { list, env }
}

// The folder a cd goes to; null when it cannot be known.
const cdTarget = (list: readonly string[]) => {
  const target = list.slice(1).find(word => !CD_FLAGS.has(word.toLowerCase()))

  return target === undefined || UNRESOLVABLE.test(target) ? null : target
}

// Global options that take their value as the next word (or after `=`).
const VALUE_OPTIONS = new Set(['-c', '--namespace', '--exec-path', '--config-env'])
// Verbs that move HEAD without a commit: with one in the command, a moved
// HEAD says nothing about the commit.
const MOVES_HEAD = new Set(['checkout', 'switch', 'reset', 'rebase', 'merge', 'pull', 'cherry-pick', 'revert', 'stash', 'am'])

const NEW_BRANCH_FLAGS: Readonly<Record<string, readonly string[]>> = {
  checkout: ['-b', '-B'],
  switch: ['-c', '-C', '--create', '--force-create'],
}
const QUIET = new Set(['-q', '--quiet'])

// The branch a `checkout -b X` / `switch -c X` creates at HEAD; null for any
// other form (a start point, a plain checkout, other options).
const newBranchOf = (verb: string | undefined, rest: readonly string[]) => {
  const flags = NEW_BRANCH_FLAGS[verb ?? '']
  const at = rest.findIndex(word => flags?.includes(word) === true)
  const name = at < 0 ? undefined : rest[at + 1]
  const others = rest.filter((_, index) => index !== at && index !== at + 1)

  return name === undefined || name.startsWith('-') || UNRESOLVABLE.test(name) || !others.every(word => QUIET.has(word))
    ? null
    : name
}

// git's global options, the verb, and the folder it works in. A git folder
// named without a work tree (`--git-dir`, `GIT_DIR`) is another repo: unknown.
const gitCall = (list: readonly string[], env: ReadonlyMap<string, string>) => {
  const dirs: string[] = []
  let isDirKnown = true
  let gitDir = env.get('GIT_DIR') ?? null
  let workTree = env.get('GIT_WORK_TREE') ?? null
  let i = 1
  while (i < list.length && list[i]!.startsWith('-')) {
    const option = list[i]!
    const cut = option.indexOf('=')
    const name = cut < 0 ? option : option.slice(0, cut)
    const inline = cut < 0 ? undefined : option.slice(cut + 1)
    if (name === '-C') {
      const dir = list[i + 1]
      if (dir === undefined || UNRESOLVABLE.test(dir)) isDirKnown = false
      else dirs.push(dir)
      i += 2
    } else if (name === '--git-dir' || name === '--work-tree') {
      const value = inline ?? list[i + 1] ?? ''
      if (name === '--git-dir') gitDir = value
      else workTree = value
      i += inline === undefined ? 2 : 1
    } else {
      i += VALUE_OPTIONS.has(name) && inline === undefined ? 2 : 1
    }
  }
  if (workTree !== null) {
    if (workTree === '' || UNRESOLVABLE.test(workTree)) isDirKnown = false
    else dirs.push(workTree)
  } else if (gitDir !== null) {
    isDirKnown = false
  }

  return { verb: list[i], rest: list.slice(i + 1), dirs, isDirKnown }
}

// The first `git commit` the command runs, the directories it runs in, and
// whether the command moves HEAD some other way too.
export const findCommit = (command: string): CommitCall | null => {
  const cds: string[] = []
  let isDirKnown = true
  let movesHead = false
  let newBranch: string | null = null
  let found: Omit<CommitCall, 'movesHead' | 'newBranch'> | null = null
  for (const segment of segments(command)) {
    const { list, env } = commandWords(segment)
    const head = list[0]?.toLowerCase()
    if (head === undefined) continue
    if (CD.has(head) && found === null) {
      const target = cdTarget(list)
      if (target === null) isDirKnown = false
      else cds.push(target)
      continue
    }
    if (POP.has(head) && found === null) {
      isDirKnown = false
      continue
    }
    if (!GIT.test(head)) continue
    const call = gitCall(list, env)
    const branch = found === null && call.dirs.length === 0 ? newBranchOf(call.verb, call.rest) : null
    if (branch !== null) newBranch = branch
    else if (MOVES_HEAD.has(call.verb ?? '')) movesHead = true
    if (found !== null || call.verb !== 'commit') continue
    if (call.rest.includes('--dry-run') || call.rest.includes('-h') || call.rest.includes('--help')) continue
    found = { dirs: [...cds, ...call.dirs], isAmend: call.rest.includes('--amend'), isDirKnown: isDirKnown && call.isDirKnown }
  }

  return found === null ? null : { ...found, movesHead, newBranch }
}

export const commitDir = (base: string, call: CommitCall) =>
  call.dirs.reduce((dir, part) => joinPath(dir, part), base)

const CLEAN = /nothing to commit, working tree clean|nothing to commit \(/i
const NOT_STAGED = /no changes added to commit|nothing added to commit/i
// Lines that say a hook failed, in order of preference. A line that only
// names a hook (`running pre-commit hook`) is no failure.
const FAILING: readonly RegExp[] = [
  /\.{3,}\s*Failed\s*$/,
  /\b(husky|pre-commit|commit-msg|prepare-commit-msg)\b.*\b(failed|exited with code [1-9]\d*|exit code [1-9]\d*)/i,
  /\blint-staged\b.*\bfailed\b/i,
  /\bhook\b.*\bfailed\b/i,
  /\bleaks? found\b/i,
  /^\s*[✖✗×]\s+\S/,
]
const ANSI = /\u001b\[[0-9;]*[A-Za-z]/g
const LINE_ROOM = 160

const hookLineOf = (output: string) => {
  const lines = output.replace(ANSI, '').split(/\r?\n/).map(line => line.trim()).filter(Boolean)
  for (const pattern of FAILING) {
    const line = lines.find(one => pattern.test(one))
    if (line !== undefined) return line.slice(0, LINE_ROOM)
  }

  return null
}

// HEAD before and after (null: no commit yet), and what the command printed.
// The caller never passes a HEAD it could not read.
export const commitOutcome = (
  before: string | null,
  after: string | null,
  output: string,
): { verdict: CommitVerdict; detail: string | null } => {
  if (after !== null && after !== before) return { verdict: 'landed', detail: null }
  if (CLEAN.test(output)) return { verdict: 'nothing', detail: null }
  if (NOT_STAGED.test(output)) return { verdict: 'failed', detail: 'nothing staged' }

  return { verdict: 'failed', detail: hookLineOf(output) }
}

export type CallFacts = {
  // A hook or a person denied the call: the command never ran.
  isDenied: boolean
  // The output reads as a refusal: judged only when HEAD did not move.
  isRefused: boolean
  isInterrupted: boolean
  // Still running when the call returned.
  isBackgrounded: boolean
  // The engine's own record of the commit it saw land.
  engineCommit: string | null
  output: string
}

type Ran = { deny?: string; isError?: boolean; text?: string; result?: unknown }

const REFUSAL = /denied this tool|doesn't want to proceed|tool use was rejected|permission .* denied/i

const fieldOf = (record: unknown, key: string): unknown =>
  typeof record === 'object' && record !== null ? (record as Record<string, unknown>)[key] : undefined

export const callFacts = (ran: Ran, input: { run_in_background?: boolean }): CallFacts => {
  const result = ran.result
  const text = typeof ran.text === 'string'
    ? ran.text
    : typeof result === 'string'
      ? result
      : [fieldOf(result, 'stdout'), fieldOf(result, 'stderr')].filter(part => typeof part === 'string').join('\n')
  const sha = fieldOf(fieldOf(fieldOf(result, 'gitOperation'), 'commit'), 'sha')
  const isBackgrounded = input.run_in_background === true ||
    typeof fieldOf(result, 'backgroundTaskId') === 'string' ||
    typeof fieldOf(result, 'timedOutAfterMs') === 'number' ||
    fieldOf(result, 'backgroundedByUser') === true ||
    fieldOf(result, 'backgroundedToDeliverMessage') === true ||
    fieldOf(result, 'backgroundedByTurnAbort') === true

  return {
    isDenied: ran.deny !== undefined,
    isRefused: ran.deny !== undefined || (ran.isError === true && REFUSAL.test(text)),
    isInterrupted: fieldOf(result, 'interrupted') === true,
    isBackgrounded,
    engineCommit: typeof sha === 'string' && sha !== '' ? sha : null,
    output: text,
  }
}

