// The to-do list: two sections, "To do" and "Uncommitted", each cut to a few
// rows with a "+n more" row; and the same list as plain text for /todo.

import type { HubRepo, HubTodo } from '../../types'
import { age, oneLine } from './format'
import { listRepos, riskyRepos } from './porcelain'

export type ListInput = {
  todos: readonly HubTodo[]
  repos: readonly HubRepo[]
  // When the repo snapshot was taken.
  reposAt: number
  now: number
}

export type Capped<T> = { shown: T[]; more: number }

export type ListModel = {
  todos: Capped<HubTodo>
  repos: Capped<HubRepo>
  reposTitle: string
  // How long ago the repos were scanned: "now", "2m ago".
  reposAgo: string
  now: number
}

export const CAPS = { todos: 8, repos: 5 } as const

const cap = <T,>(list: readonly T[], room: number): Capped<T> => ({
  shown: list.slice(0, room),
  more: Math.max(0, list.length - room),
})

const join = (parts: readonly (string | null)[]) => parts.filter((part): part is string => part !== null && part !== '').join(' · ')

export const todoLine = (todo: HubTodo, now: number) =>
  `☐ ${join([oneLine(todo.title), todo.detail === null ? null : oneLine(todo.detail), todo.project, age(todo.eventAt, now)])}`

// What is at risk in a repo, without its name.
export const repoFacts = (repo: HubRepo, now: number) => join([
  repo.files > 0 ? `${repo.files} ${repo.files === 1 ? 'file' : 'files'}` : null,
  repo.newestAt !== null ? age(repo.newestAt, now) : null,
  repo.ahead > 0 ? `↑${repo.ahead}` : null,
  repo.hasCommits && !repo.hasUpstream ? 'no remote' : null,
  repo.hasCommits ? null : 'no commits',
  repo.isIgnored ? 'ignored' : null,
])

export const repoLine = (repo: HubRepo, now: number) => join([repo.name, repoFacts(repo, now)])

const agoOf = (at: number, now: number) => {
  const text = age(at, now)

  return text === 'now' ? 'now' : `${text} ago`
}

export const listModel = (input: ListInput): ListModel => ({
  todos: cap(input.todos, CAPS.todos),
  repos: cap(listRepos(input.repos, input.now), CAPS.repos),
  reposTitle: `Uncommitted · ${agoOf(input.reposAt, input.now)}`,
  reposAgo: agoOf(input.reposAt, input.now),
  now: input.now,
})

export const isEmptyList = (model: ListModel) => model.todos.shown.length === 0 && model.repos.shown.length === 0

const section = <T,>(title: string, list: Capped<T>, line: (item: T) => string, more = '') =>
  list.shown.length === 0 ? [] : [
    title,
    ...list.shown.map(item => `  ${line(item)}`),
    ...(list.more > 0 ? [`  +${list.more} more${more}`] : []),
  ]

export const NO_ITEMS = 'No open items'

export const listText = (model: ListModel) => isEmptyList(model) ? NO_ITEMS : [
  ...section('To do', model.todos, todo => todoLine(todo, model.now)),
  ...section(model.reposTitle, model.repos, repo => `⚠ ${repoLine(repo, model.now)}`, ' · /dirty'),
].join('\n')

// Every scanned repo with something at risk, ignored and old ones included.
export const dirtyText = (repos: readonly HubRepo[], now: number) => {
  const list = riskyRepos(repos)

  return list.length === 0 ? 'No uncommitted work' : list.map(repo => `⚠ ${repoLine(repo, now)}`).join('\n')
}

