// The plugin's userConfig values, with the manifest's defaults behind them.

export type Options = {
  todo: boolean
  commitGuard: boolean
  scanRoots: string[]
  ignoreRepos: string[]
}

export const DEFAULTS: Options = {
  todo: true,
  commitGuard: true,
  scanRoots: ['~/dev', '~/code', '~/Documents'],
  ignoreRepos: [],
}

const flag = (value: unknown, fallback: boolean) => (typeof value === 'boolean' ? value : fallback)

const list = (value: unknown, fallback: string[]) => {
  if (typeof value === 'string') return value.trim() === '' ? [] : [value]

  return Array.isArray(value) ? value.filter((one): one is string => typeof one === 'string') : fallback
}

export const readOptions = (raw: Readonly<Record<string, unknown>>): Options => ({
  todo: flag(raw.todo, DEFAULTS.todo),
  commitGuard: flag(raw.commitGuard, DEFAULTS.commitGuard),
  scanRoots: list(raw.scanRoots, DEFAULTS.scanRoots),
  ignoreRepos: list(raw.ignoreRepos, DEFAULTS.ignoreRepos),
})

