// One file per running session in <config>/sessions/<pid>.json, written by
// every Claude Code process (desktop, CLI, SDK).

import { num, parseObject, pick, str } from './json'

export type Entry = {
  pid: number
  sessionId: string
  cwd?: string
  name?: string
  // busy | shell | waiting | idle (see statusKind)
  status?: string
  waitingFor?: string
  statusUpdatedAt?: number
  updatedAt?: number
  startedAt?: number
  kind?: string
  entrypoint?: string
  hostSessionId?: string
  // The file's mtime, from the listing.
  writtenAt?: number
}

const TEXT_FIELDS = ['cwd', 'name', 'status', 'waitingFor', 'kind', 'entrypoint', 'hostSessionId'] as const
const TIME_FIELDS = ['statusUpdatedAt', 'updatedAt', 'startedAt'] as const

export const parseEntry = (text: string | null): Entry | null => {
  const raw = parseObject(text)
  const pid = num(raw?.pid)
  const sessionId = str(raw?.sessionId)
  if (raw === null || pid === undefined || sessionId === undefined) return null

  return {
    pid,
    sessionId,
    ...pick(raw, TEXT_FIELDS, str),
    ...pick(raw, TIME_FIELDS, num),
  } as Entry
}

export const DESKTOP = 'claude-desktop'

// A chat a person has open: the desktop's (`claude-desktop`, with its desktop
// id) or a terminal's. Background SDK sessions (`sdk-cli`: memory observers,
// `claude -p` runs) are not the person's own conversations; nor is a
// `claude -p` started from a desktop chat's shell, which inherits the desktop
// entrypoint but gets no desktop id.
export const isPersonChat = (entry: Entry | null | undefined) =>
  entry !== null && entry !== undefined &&
  (entry.kind === undefined || entry.kind === 'interactive') &&
  !(entry.entrypoint ?? '').startsWith('sdk') &&
  (entry.entrypoint !== DESKTOP || entry.hostSessionId !== undefined)

export const isPersonal = (entry: Entry, selfId: string) => entry.sessionId !== selfId && isPersonChat(entry)

// The statuses the engine writes (2.1.299): `busy` (a turn runs), `shell` (the
// turn ended, a background shell still runs: the engine draws it as working),
// `waiting` (with `waitingFor`) and `idle`. Anything else counts as idle,
// never as needing the user.
export type StatusKind = 'working' | 'waiting' | 'idle'

export const statusKind = (status: string | undefined): StatusKind =>
  status === 'busy' || status === 'shell' ? 'working' : status === 'waiting' ? 'waiting' : 'idle'

const LIVE_STALE_MS = 24 * 60 * 60 * 1000

// A pid in the claude.exe list is not proof on its own: the desktop app's own
// processes are claude.exe too, and pids are reused. A file also has to be
// written within a day, or say the session is working or waiting. `pids`
// null: the list could not be read, and every file counts as running.
export const isLiveEntry = (entry: Entry, pids: ReadonlySet<number> | null, now: number) =>
  pids === null || (pids.has(entry.pid) &&
    (statusKind(entry.status) !== 'idle' || now - Math.max(entry.updatedAt ?? 0, entry.writtenAt ?? 0) < LIVE_STALE_MS))

