// Opens a session link or a file the way the desktop does: through the shell
// handler (links inside the desktop are https-only, so claude:// goes this way).

import type { EngineInterface } from 'claude-code'

export async function openTarget($: EngineInterface, target: string, isWindows: boolean) {
  const argv = isWindows ? ['explorer.exe', target] : ['open', target]
  // explorer.exe exits 1 even when it opened the target: only a failed start counts.
  await $.process.run(argv, { timeoutMs: 10000 }).catch(() => {
    $.ui.toast('Could not open that')
  })
}

