// Where things live on this machine. The variable names are literals: the
// engine reads them off the source.

import type { EngineInterface } from 'claude-code'

export type Place = {
  isWindows: boolean
  sep: string
  home: string | null
  // <config>/sessions: the registry of running sessions.
  registry: string
  // The desktop app's session records, or null off the desktop.
  app: string | null
  // The last usage reading, shared by every session.
  shared: string
  selfId: string
}

export async function findPlace($: EngineInterface): Promise<Place | null> {
  const isWindows = (await $.env.get('OS')) === 'Windows_NT'
  const sep = isWindows ? '\\' : '/'
  const home = isWindows ? await $.env.get('USERPROFILE') : await $.env.get('HOME')
  const config = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? (home === undefined ? null : `${home}${sep}.claude`)
  if (config === null) return null
  const appData = isWindows
    ? await $.env.get('APPDATA')
    : home === undefined ? undefined : `${home}/Library/Application Support`

  return {
    isWindows,
    sep,
    home: home ?? null,
    registry: `${config}${sep}sessions`,
    app: appData === undefined ? null : `${appData}${sep}Claude${sep}claude-code-sessions`,
    shared: `${config}${sep}mods${sep}session-hub-usage.json`,
    selfId: await $.session.id(),
  }
}

