// Reads the session registry and the desktop app's records, re-reading only
// files whose mtime moved.

import type { EngineInterface } from 'claude-code'

import { parseDesktop } from '../lib/desktop'
import type { Desktop } from '../lib/desktop'
import { isLiveEntry, isPersonal, parseEntry } from '../lib/registry'
import type { Entry } from '../lib/registry'
import type { Place } from './place'

const ALIVE_MS = 60000
const APP_DIRS_MS = 10 * 60 * 1000
const RECENT_MS = 48 * 60 * 60 * 1000
const TASKLIST_MS = 10000

type Cached<T> = { mtimeMs: number; value: T | null }

export type SessionCache = {
  entries: Map<string, Cached<Entry>>
  desktops: Map<string, Map<string, Cached<Desktop>>>
  appDirs: string[] | null
  appDirsAt: number
  alive: Set<number> | null
  aliveAt: number
}

export const newSessionCache = (): SessionCache => ({
  entries: new Map(), desktops: new Map(), appDirs: null, appDirsAt: 0, alive: null, aliveAt: 0,
})

export type SessionRead = {
  entries: Entry[]
  alive: Set<number> | null
  desktop: Map<string, Desktop>
  // This session's own desktop id and process, for links and the home record.
  selfHost: string | null
  selfPid: number | null
  // Session ids and desktop ids of every running session, this one included.
  liveIds: Set<string>
  // Session ids of running sessions in a turn, this one included.
  busyIds: Set<string>
}

// Every session runs as claude.exe (checked on this machine): a pid alive
// under another name is a reused pid, so its registry file is dead (the
// desktop app's own processes are claude.exe too: lib/registry.ts isLiveEntry).
// Null: the list could not be read, and every file counts as running.
async function livePids($: EngineInterface, isWindows: boolean) {
  const argv = isWindows
    ? ['tasklist', '/FI', 'IMAGENAME eq claude.exe', '/FO', 'CSV', '/NH']
    : ['ps', '-A', '-o', 'pid=']
  try {
    const { stdout } = await $.process.run(argv, { timeoutMs: TASKLIST_MS })
    const pattern = isWindows ? /^"claude\.exe","(\d+)"/gim : /^\s*(\d+)\s*$/gm
    const pids = new Set([...stdout.matchAll(pattern)].map(match => Number(match[1])))

    // This session is one of them, so an empty list is a list that failed.
    return pids.size > 0 ? pids : null
  } catch {
    return null
  }
}

async function refresh<T>(
  $: EngineInterface,
  dir: string,
  sep: string,
  cache: Map<string, Cached<T>>,
  keep: (name: string, mtimeMs: number) => boolean,
  parse: (text: string | null) => T | null,
) {
  const listed = (await $.fs.list(dir)).filter(file => file.kind === 'file' && keep(file.name, file.mtimeMs))
  const names = new Set(listed.map(file => file.name))
  for (const name of [...cache.keys()]) {
    if (!names.has(name)) cache.delete(name)
  }
  for (const file of listed) {
    if (cache.get(file.name)?.mtimeMs === file.mtimeMs) continue
    const text = await $.fs.read(`${dir}${sep}${file.name}`).catch(() => null)
    cache.set(file.name, { mtimeMs: file.mtimeMs, value: parse(typeof text === 'string' ? text : null) })
  }
}

// The app keeps sessions under <app>/<account>/<organization>/local_<id>.json.
async function findAppDirs($: EngineInterface, app: string, sep: string) {
  const found: string[] = []
  const accounts = await $.fs.list(app).catch(() => [])
  for (const account of accounts.filter(entry => entry.kind === 'dir')) {
    const orgs = await $.fs.list(`${app}${sep}${account.name}`).catch(() => [])
    for (const org of orgs.filter(entry => entry.kind === 'dir')) {
      found.push(`${app}${sep}${account.name}${sep}${org.name}`)
    }
  }

  return found
}

// The registry alone (no process list): every entry, this session's included,
// with its file's mtime.
export async function readRegistry($: EngineInterface, place: Place, cache: SessionCache): Promise<Entry[]> {
  await refresh($, place.registry, place.sep, cache.entries, name => name.endsWith('.json'), parseEntry)

  return [...cache.entries.values()].flatMap(file => (file.value === null ? [] : [{ ...file.value, writtenAt: file.mtimeMs }]))
}

export async function readSessions(
  $: EngineInterface,
  place: Place,
  cache: SessionCache,
  now: number,
): Promise<SessionRead> {
  const all = await readRegistry($, place, cache)
  if (now - cache.aliveAt >= ALIVE_MS) {
    cache.aliveAt = now
    cache.alive = await livePids($, place.isWindows)
  }
  const pids = cache.alive
  const alive = pids === null ? null : new Set(all.filter(entry => isLiveEntry(entry, pids, now)).map(entry => entry.pid))
  const running = all.filter(entry => alive === null || alive.has(entry.pid))
  const liveHosts = new Set(running.flatMap(entry => entry.hostSessionId ?? []))

  // A running session's record is read whatever its age: its focus matters.
  const desktop = new Map<string, Desktop>()
  if (place.app !== null) {
    if (cache.appDirs === null || now - cache.appDirsAt >= APP_DIRS_MS) {
      cache.appDirsAt = now
      cache.appDirs = await findAppDirs($, place.app, place.sep)
    }
    for (const dir of cache.appDirs) {
      const files = cache.desktops.get(dir) ?? new Map<string, Cached<Desktop>>()
      cache.desktops.set(dir, files)
      await refresh($, dir, place.sep, files,
        (name, mtimeMs) => name.startsWith('local_') && name.endsWith('.json') &&
          (now - mtimeMs < RECENT_MS || liveHosts.has(name.slice(0, -'.json'.length))),
        parseDesktop).catch(() => undefined)
      for (const [name, file] of files) {
        if (file.value !== null) desktop.set(name.slice(0, -'.json'.length), { ...file.value, writtenAt: file.mtimeMs })
      }
    }
  }

  const self = all.find(entry => entry.sessionId === place.selfId)
  // The bar names running sessions only.
  const entries = running.filter(entry => isPersonal(entry, place.selfId))

  return {
    entries,
    alive,
    desktop,
    selfHost: self?.hostSessionId ?? null,
    selfPid: self?.pid ?? null,
    // This chat runs, whatever its file says.
    liveIds: new Set([...running, ...(self === undefined ? [] : [self])]
      .flatMap(entry => [entry.sessionId, ...(entry.hostSessionId ?? [])])),
    busyIds: new Set(running.filter(entry => entry.status === 'busy').map(entry => entry.sessionId)),
  }
}

