// Keeping memory and $.store in step, with two fields. A write counts as under
// way (`inFlight`) from before memory changes until the store has it; once it
// lands the revision is owed a bump (`seenRev` null), paid once at the end of
// the batch (`flushRev`). A reload is skipped while a write is under way or a
// bump is owed, and thrown away when either began during it, so a Done never
// flickers back.

import type { EngineInterface } from 'claude-code'

import { hub } from './hub'
import { pendingId } from './lib/checks'
import type { DirtyCheck, PendingCommit } from './lib/checks'
import type { TodoItem, TodoState } from './lib/todo'
import {
  bumpRev, dropCheck, dropItem, dropPending, dropState, loadAll, loadItem, loadPending, loadRev, newRev, writeCheck,
  writeItem, writePending, writeState,
} from './sources/store'

// Memory changes at once (before the first await), the store after.
async function storeWrite(apply: () => void, work: () => Promise<void>) {
  hub.inFlight += 1
  apply()
  try {
    await work()
  } finally {
    hub.inFlight -= 1
    hub.seenRev = null
  }
}

export async function putItem($: EngineInterface, item: TodoItem) {
  await storeWrite(() => hub.items.set(item.id, item), () => writeItem($, item))
}

export async function removeItem($: EngineInterface, id: string) {
  await storeWrite(() => {
    hub.items.delete(id)
    hub.states.delete(id)
  }, () => dropItem($, id))
}

export async function putState($: EngineInterface, id: string, state: TodoState) {
  await storeWrite(() => hub.states.set(id, state), () => writeState($, id, state))
}

export async function removeState($: EngineInterface, id: string) {
  await storeWrite(() => hub.states.delete(id), () => dropState($, id))
}

export async function putPending($: EngineInterface, pending: PendingCommit) {
  const id = pendingId(pending.repo)
  await storeWrite(() => hub.pending.set(id, pending), () => writePending($, id, pending))
}

export async function removePending($: EngineInterface, id: string) {
  await storeWrite(() => hub.pending.delete(id), () => dropPending($, id))
}

export async function putCheck($: EngineInterface, id: string, check: DirtyCheck) {
  await storeWrite(() => hub.checks.set(id, check), () => writeCheck($, id, check))
}

export async function removeCheck($: EngineInterface, id: string) {
  await storeWrite(() => hub.checks.delete(id), () => dropCheck($, id))
}

// The batch's one bump. The sentinel is set first, so a write that lands
// during the bump owes its own.
export async function flushRev($: EngineInterface) {
  if (hub.seenRev !== null) return
  const rev = newRev()
  hub.seenRev = `~${rev}`
  try {
    await bumpRev($, rev)
  } catch (error) {
    hub.seenRev = null
    throw error
  }
}

// Reloads every item, state and check only when another write moved the
// revision.
export async function reloadIfMoved($: EngineInterface) {
  if (hub.inFlight > 0 || hub.seenRev === null) return
  // Taken before the revision read, so a write that lands during it is seen.
  const before = hub.seenRev
  const rev = await loadRev($)
  if (rev === before || hub.inFlight > 0 || hub.seenRev !== before) return
  const loaded = await loadAll($)
  if (hub.inFlight > 0 || hub.seenRev !== before) return
  Object.assign(hub, loaded)
  hub.seenRev = rev
}

// Memory as the store has it now (at a chat's start, and before a command
// answers from it): an owed bump paid first, then a reload if anything moved.
export async function loadNow($: EngineInterface) {
  await flushRev($)
  await reloadIfMoved($)
}

// The item in memory, else the stored one (a headless run keeps none).
export async function storedItem($: EngineInterface, id: string) {
  return hub.items.get(id) ?? (await loadItem($, id).catch(() => null)) ?? undefined
}

export async function storedPending($: EngineInterface, id: string) {
  return hub.pending.get(id) ?? (await loadPending($, id).catch(() => null)) ?? undefined
}

// One step at a time per name; a step that throws shows nothing and the next
// tick tries again. Each step is a batch: it ends with the revision's one bump.
export async function step($: EngineInterface, name: string, work: () => Promise<void>) {
  if (hub.running.has(name)) return
  hub.running.add(name)
  try {
    await work()
  } catch {
    // A source can vanish between ticks.
  } finally {
    hub.running.delete(name)
    await flushRev($).catch(() => undefined)
  }
}

