// Sessions into the bar's rows and into to-dos, and the user's Done and
// Snooze. Session items come and go here; commit and dirty items only
// through git (repo-checks.ts).

import type { EngineInterface } from 'claude-code'

import type { HubTodo } from '../types'
import { hub, openItems, publish } from './hub'
import { classify } from './lib/sessions'
import { autoDone, doneState, prune, sessionItemId, sessionUpdates, snoozeState } from './lib/todo'
import type { TodoItem, TodoState } from './lib/todo'
import { readSessions } from './sources/sessions'
import { readLimits } from './sources/usage'
import { flushRev, putItem, putState, removeItem, removeState } from './store-sync'

export async function addItem($: EngineInterface, item: TodoItem, at: number) {
  await putItem($, item)
  await publish($, { todos: openItems(at) })
}

export async function tickSessions($: EngineInterface) {
  const place = hub.place
  if (place === null) return
  const at = await $.clock.now()
  // A /clear gives this session a new id: read it every time.
  place.selfId = await $.session.id()
  const read = await readSessions($, place, hub.sessions, at)
  hub.selfHost = read.selfHost
  hub.selfPid = read.selfPid
  hub.liveIds = read.liveIds
  hub.busyIds = read.busyIds
  const result = classify({
    entries: read.entries, alive: read.alive, desktop: read.desktop, now: at, selfHost: read.selfHost,
  })
  hub.rows = result.rows
  hub.facts = result.facts
  hub.finishes = result.finishes
  await publish($, {
    rows: result.rows,
    now: Math.floor(at / 60000) * 60000,
    limits: await readLimits($, place.shared, hub.usage),
  })
  if (!hub.options.todo) return
  for (const item of sessionUpdates(result.finishes, hub.items)) await putItem($, item)
  // Continued or archived sessions.
  for (const id of autoDone(hub.items, hub.facts)) await removeItem($, id)
  await publish($, { todos: openItems(at) })
}

// Done items older than 7 days go, unless detection would bring them back.
export async function prunePass($: EngineInterface, at: number) {
  const keep = new Set([
    ...hub.finishes.map(finish => sessionItemId(finish.key)),
    ...hub.rows.map(row => sessionItemId(row.key)),
    // This chat's own session: other chats see its finish, this one cannot.
    ...(hub.selfHost === null ? [] : [sessionItemId(hub.selfHost)]),
  ])
  const pruned = prune(hub.items, hub.states, at, keep)
  for (const id of pruned.items) await removeItem($, id)
  for (const id of pruned.states) if (hub.states.has(id)) await removeState($, id)
}

// The user's actions, from the list's buttons. Memory changes as the write
// starts, before the drawing, so a reload never shows the old state.
async function act($: EngineInterface, id: string, state: TodoState, at: number) {
  const write = putState($, id, state)
  await publish($, { todos: openItems(at) })
  await write
  await flushRev($)
}

export async function markDone($: EngineInterface, todo: HubTodo) {
  const at = await $.clock.now()
  await act($, todo.id, doneState(todo, at), at)
}

export async function snooze($: EngineInterface, todo: HubTodo) {
  const at = await $.clock.now()
  await act($, todo.id, snoozeState(todo, hub.states.get(todo.id), at), at)
}

