// The bar: per session a mark, the name
// (opens the chat) and a dim age, wrapping as needed; then `☐ n` and `⚠ n`
// (open the to-do list); the 5h and week meters on the right.

import type { EngineInterface, ResolveInput } from 'claude-code'

import type { HubLimit, HubRow } from '../../types'
import { limitView, MARK, NAME_ROOM } from '../lib/bar'
import { age, clip } from '../lib/format'

export type BarInput = { rows: readonly HubRow[]; todo: number; risk: number; limits: readonly HubLimit[]; now: number }

export type BarActions = {
  openSession: (link: string) => void
  openList: () => void
}

export function drawBar($: EngineInterface, e: ResolveInput, input: BarInput, act: BarActions) {
  const { Box, Text, Button } = $.ui.resolve(e)

  return (
    <Box flexDirection="row" justifyContent="space-between" columnGap={2}>
      <Box flexDirection="row" flexWrap="wrap" columnGap={2}>
        {input.rows.map(row => {
          const mark = MARK[row.state]
          const name = clip(row.name, NAME_ROOM)
          const link = row.link

          return (
            <Box flexDirection="row" gap={1}>
              <Text color={mark.color}>{mark.glyph}</Text>
              {link === null
                ? <Text>{name}</Text>
                : <Button key={`open:${row.key}`} plain label={name} onPress={() => act.openSession(link)} />}
              <Text dimColor>{age(row.since, input.now)}</Text>
            </Box>
          )
        })}
        {input.todo > 0 && <Button key="todo" plain label={`☐ ${input.todo}`} onPress={() => act.openList()} />}
        {input.risk > 0 && (
          <Button key="risk" plain onPress={() => act.openList()}>
            <Text color="warning">{`⚠ ${input.risk}`}</Text>
          </Button>
        )}
      </Box>
      <Box flexDirection="row" columnGap={2}>
        {input.limits.map(limit => {
          const view = limitView(limit, input.now)

          return (
            <Box flexDirection="row" gap={1}>
              <Text dimColor>{view.label}</Text>
              <Text color={view.color}>{`${view.percent}%`}</Text>
              {view.reset !== null && <Text dimColor>{`↻${view.reset}`}</Text>}
            </Box>
          )
        })}
      </Box>
    </Box>
  )
}

