// Paints the to-do list (lib/list.ts) as cards: one per to-do, with its
// title, last status, project and age, and Open, Snooze and Done inside the
// card, so each button sits with its item; then the uncommitted repos in one.

import type { EngineInterface, ResolveInput } from 'claude-code'

import type { HubRepo, HubTodo } from '../../types'
import { age, oneLine } from '../lib/format'
import { isEmptyList, NO_ITEMS, repoFacts } from '../lib/list'
import type { ListModel } from '../lib/list'

export type ListActions = {
  openSession: (link: string) => void
  done: (todo: HubTodo) => void
  snooze: (todo: HubTodo) => void
}

export function drawList($: EngineInterface, e: ResolveInput, model: ListModel, act: ListActions) {
  const { Box, Text, Button } = $.ui.resolve(e)

  const header = (title: string, note: string) => (
    <Box flexDirection="row" columnGap={1}>
      <Text bold>{title}</Text>
      <Text dimColor>{note}</Text>
    </Box>
  )

  const more = (count: number, hint = '') => count > 0 && <Text dimColor>{`+${count} more${hint}`}</Text>

  const card = (todo: HubTodo) => {
    const link = todo.link
    const title = oneLine(todo.title)

    return (
      <Box
        key={`item:${todo.id}`}
        flexDirection="column"
        paddingX={1}
        borderStyle="round"
        borderColor={todo.isRisk ? 'warning' : undefined}
        borderDimColor
        hover={{ borderColor: todo.isRisk ? 'warning' : 'claude', borderDimColor: false }}
      >
        <Box flexDirection="row" columnGap={2}>
          <Box flexGrow={1} flexShrink={1}>
            <Text bold color={todo.isRisk ? 'warning' : undefined} wrap="truncate-end">{todo.isRisk ? `⚠ ${title}` : title}</Text>
          </Box>
          <Text dimColor>{age(todo.eventAt, model.now)}</Text>
        </Box>
        {todo.detail !== null && <Text dimColor wrap="truncate-end">{oneLine(todo.detail)}</Text>}
        <Box flexDirection="row" columnGap={2} alignItems="center">
          <Box flexGrow={1} flexShrink={1}>
            {todo.project !== null && <Text color="suggestion" wrap="truncate-end">{todo.project}</Text>}
          </Box>
          <Box flexDirection="row" flexShrink={0} columnGap={1}>
            {link !== null && <Button key={`open-todo:${todo.id}`} dimColor label="Open" onPress={() => act.openSession(link)} />}
            <Button key={`snooze:${todo.id}`} dimColor label="Snooze" onPress={() => act.snooze(todo)} />
            <Button key={`done:${todo.id}`} label="Done" onPress={() => act.done(todo)} />
          </Box>
        </Box>
      </Box>
    )
  }

  const repoRow = (repo: HubRepo) => (
    <Box flexDirection="row" columnGap={2}>
      <Box flexGrow={1} flexShrink={1}>
        <Text color="warning" wrap="truncate-end">{`⚠ ${repo.name}`}</Text>
      </Box>
      <Text dimColor>{repoFacts(repo, model.now)}</Text>
    </Box>
  )

  const todos = model.todos
  const repos = model.repos

  return (
    <Box flexDirection="column" rowGap={1}>
      {todos.shown.length > 0 && (
        <Box flexDirection="column">
          {header('To do', String(todos.shown.length + todos.more))}
          {todos.shown.map(card)}
          {more(todos.more)}
        </Box>
      )}
      {repos.shown.length > 0 && (
        <Box flexDirection="column">
          {header('Uncommitted', `checked ${model.reposAgo}`)}
          <Box flexDirection="column" paddingX={1} borderStyle="round" borderColor="warning" borderDimColor>
            {repos.shown.map(repoRow)}
          </Box>
          {more(repos.more, ' · /dirty')}
        </Box>
      )}
      {isEmptyList(model) && <Text dimColor>{NO_ITEMS}</Text>}
    </Box>
  )
}

