// Which chat shows the to-do list (the home): the one `/todo here` was typed
// in, known by its CLI session id or by the desktop's id, which survives a
// process restart.

export type Home = { sessionId: string; hostSessionId: string | null; pid: number | null }

export const isHomeChat = (home: Home | null, selfId: string, selfHost: string | null) =>
  home !== null &&
  (home.sessionId === selfId || (home.hostSessionId !== null && home.hostSessionId === selfHost))

// A home counts only while a running session carries its id; a closed or
// archived home is no home, and `/todo` then scans on demand.
export const isHomeAlive = (home: Home | null, liveIds: ReadonlySet<string>) =>
  home !== null &&
  (liveIds.has(home.sessionId) || (home.hostSessionId !== null && liveIds.has(home.hostSessionId)))

