// To-do rules. Items live in $.store one key per item: `todo:<id>` written by
// detection, `todo-state:<id>` by the user's Done and Snooze. Nothing here
// touches the store; the adapter applies what these functions return.

import type { HubTodo, HubTodoKind } from '../../types'
import { isCommitEntry } from './gitfs'
import type { Head, ReflogEntry } from './gitfs'
import { isObject, num, pick, str } from './json'
import { basename, repoKey } from './paths'
import { isTurnEnd } from './sessions'
import type { Facts, Finish } from './sessions'

export type TodoItem = {
  id: string
  kind: HubTodoKind
  title: string
  detail: string | null
  project: string | null
  link: string | null
  eventAt: number
  createdAt: number
  // commit and dirty items: the repo's real path.
  repo?: string
  // dirty items: the uncommitted files it is about; it clears when all are clean.
  paths?: string[]
  // commit items: HEAD when the commit failed; a later commit on that branch resolves it.
  headSha?: string | null
  headRef?: string | null
}

export type TodoState = {
  doneAt?: number
  // The eventAt that Done answered; a newer event opens the item again.
  doneFor?: number
  snoozeUntil?: number
  snoozes?: number
  // The eventAt the snooze answered; a newer event shows at once.
  snoozeFor?: number
}

const HOUR = 60 * 60 * 1000
const DAY = 24 * HOUR
export const SNOOZE_MS = 3 * HOUR
export const PRUNE_MS = 7 * DAY
// One finish read from the registry and, after the process exits, from the
// desktop record is dated a few ms apart: within this it is the same event.
export const SAME_EVENT_MS = 5000
const SLACK_MS = 5000
const MORNING_HOUR = 8
const ID_ROOM = 200
const TITLE_ROOM = 300

const KINDS: readonly HubTodoKind[] = ['session', 'commit', 'dirty', 'manual']

const isSameEvent = (a: number, b: number) => Math.abs(a - b) <= SAME_EVENT_MS

// What the store hands back is whatever some version wrote: check it.
export const parseItem = (value: unknown): TodoItem | null => {
  if (!isObject(value)) return null
  const id = str(value.id)
  const kind = KINDS.find(one => one === value.kind)
  const title = str(value.title)
  const eventAt = num(value.eventAt)
  if (id === undefined || kind === undefined || title === undefined || eventAt === undefined) return null
  const repo = str(value.repo)
  const paths = Array.isArray(value.paths) ? value.paths.filter((path): path is string => typeof path === 'string') : undefined
  const headSha = value.headSha === null ? null : str(value.headSha)
  const headRef = value.headRef === null ? null : str(value.headRef)

  return {
    id,
    kind,
    title,
    detail: str(value.detail) ?? null,
    project: str(value.project) ?? null,
    link: str(value.link) ?? null,
    eventAt,
    createdAt: num(value.createdAt) ?? eventAt,
    ...(repo === undefined ? {} : { repo }),
    ...(paths === undefined ? {} : { paths }),
    ...(headSha === undefined ? {} : { headSha }),
    ...(headRef === undefined ? {} : { headRef }),
  }
}

const STATE_FIELDS = ['doneAt', 'doneFor', 'snoozeUntil', 'snoozes', 'snoozeFor'] as const

export const parseState = (value: unknown): TodoState | null =>
  isObject(value) ? (pick(value, STATE_FIELDS, num) as TodoState) : null

// FNV-1a, enough to keep a store key short and stable.
const hash = (text: string) => {
  let value = 0x811c9dc5
  for (let i = 0; i < text.length; i += 1) {
    value ^= text.charCodeAt(i)
    value = Math.imul(value, 0x01000193) >>> 0
  }

  return value.toString(16).padStart(8, '0')
}

// Store keys are capped at 256 characters.
export const shortId = (id: string) => (id.length <= ID_ROOM ? id : `${id.slice(0, ID_ROOM - 9)}~${hash(id)}`)

export const sessionItemId = (key: string) => shortId(`s:${key}`)

// Items to write for this scan's finishes: new ones, a newer finish, and a
// summary (or title) that arrived after the item was written. Detection never
// removes an item, and never wipes a detail it already has.
export const sessionUpdates = (finishes: readonly Finish[], items: ReadonlyMap<string, TodoItem>) => {
  const updates: TodoItem[] = []
  for (const finish of finishes) {
    const id = sessionItemId(finish.key)
    const stored = items.get(id)
    const isSame = stored !== undefined && isSameEvent(stored.eventAt, finish.at)
    const hasNews = isSame &&
      ((finish.detail !== null && finish.detail !== stored.detail) || finish.title !== stored.title)
    if (stored !== undefined && !isSame && stored.eventAt > finish.at) continue
    if (isSame && !hasNews) continue
    updates.push({
      id,
      kind: 'session',
      title: finish.title,
      detail: finish.detail ?? (isSame ? stored.detail : null),
      project: finish.project,
      link: finish.link,
      // The same event keeps its first date, so Done and Snooze keep applying.
      eventAt: isSame ? stored.eventAt : finish.at,
      createdAt: stored?.createdAt ?? finish.at,
    })
  }

  return updates
}

export const commitItemId = (repo: string) => shortId(`c:${repoKey(repo)}`)

// One item per repo: a new failed attempt replaces the last one's detail.
export const commitItem = (
  args: { repo: string; at: number; detail: string | null; link: string | null; head: Head | null },
): TodoItem => ({
  id: commitItemId(args.repo),
  kind: 'commit',
  title: 'Commit did not land',
  detail: args.detail,
  project: basename(args.repo),
  repo: args.repo,
  link: args.link,
  eventAt: args.at,
  createdAt: args.at,
  ...(args.head === null ? {} : { headSha: args.head.sha, headRef: args.head.ref }),
})

// A commit landed on the branch the failure was on, by anyone (a hand-made
// one in a terminal too, or a cherry-pick): the branch's reflog has a commit
// entry newer than the item, whatever moved it after (a pull, a rebase) and
// wherever HEAD is now. A pull, reset or merge alone commits nothing new.
export const commitResolved = (item: TodoItem, moves: readonly ReflogEntry[]) =>
  moves.some(move => isCommitEntry(move.message) && move.at + 1000 > item.eventAt)

export const dirtyItemId = (repo: string) => shortId(`d:${repoKey(repo)}`)

// Dated from the latest edit, so Done holds until that repo is edited again.
export const dirtyItem = (args: { repo: string; lastEditAt: number; paths: readonly string[]; link: string | null }): TodoItem => ({
  id: dirtyItemId(args.repo),
  kind: 'dirty',
  title: 'Uncommitted',
  detail: `${args.paths.length} ${args.paths.length === 1 ? 'file' : 'files'}`,
  project: basename(args.repo),
  repo: args.repo,
  link: args.link,
  eventAt: args.lastEditAt,
  createdAt: args.lastEditAt,
  paths: [...args.paths],
})

// What to write for a dirty check that found files still uncommitted: the
// new item, a newer edit, or changed files; null when nothing changed.
export const dirtyUpdate = (stored: TodoItem | undefined, next: TodoItem): TodoItem | null => {
  if (stored === undefined) return next
  if (next.eventAt < stored.eventAt) return null
  const isSamePaths = JSON.stringify([...(stored.paths ?? [])].sort()) === JSON.stringify([...(next.paths ?? [])].sort())
  if (next.eventAt === stored.eventAt && next.detail === stored.detail && isSamePaths) return null

  return { ...next, createdAt: stored.createdAt }
}

export const manualItem = (text: string, now: number, nonce: string): TodoItem => ({
  id: `m:${now}-${nonce}`,
  kind: 'manual',
  title: text.slice(0, TITLE_ROOM),
  detail: null,
  project: null,
  link: null,
  eventAt: now,
  createdAt: now,
})

const doneCovers = (state: TodoState | undefined, eventAt: number) =>
  state?.doneAt !== undefined && (state.doneFor ?? Number.POSITIVE_INFINITY) + SAME_EVENT_MS >= eventAt

export const isDone = (item: TodoItem, state: TodoState | undefined) => doneCovers(state, item.eventAt)

const isSnoozed = (item: TodoItem, state: TodoState | undefined, now: number) =>
  state?.snoozeUntil !== undefined && state.snoozeUntil > now &&
  (state.snoozeFor === undefined || isSameEvent(state.snoozeFor, item.eventAt))

export const isRiskKind = (kind: HubTodoKind) => kind === 'commit' || kind === 'dirty'

export const openTodos = (
  items: ReadonlyMap<string, TodoItem>,
  states: ReadonlyMap<string, TodoState>,
  now: number,
): HubTodo[] =>
  [...items.values()]
    .filter(item => !isDone(item, states.get(item.id)) && !isSnoozed(item, states.get(item.id), now))
    .sort((a, b) => a.eventAt - b.eventAt || a.id.localeCompare(b.id))
    .map(item => ({
      id: item.id,
      kind: item.kind,
      title: item.title,
      detail: item.detail,
      project: item.project,
      link: item.link,
      eventAt: item.eventAt,
      isRisk: isRiskKind(item.kind),
    }))

// The user went back to the session after it finished and a real turn ran:
// the desktop saw activity after the focus, or the registry's status changed
// after the focus by a turn's end (isTurnEnd: a process start alone never
// counts).
const hasContinued = (fact: Facts, eventAt: number) => {
  const focusedAt = fact.focusedAt
  if (focusedAt === null || focusedAt <= eventAt) return false
  const isActive = fact.activityAt !== null && fact.activityAt > focusedAt + SLACK_MS
  const isTurn = fact.statusAt !== null && fact.statusAt > focusedAt &&
    isTurnEnd(fact.statusAt, fact.startedAt, fact.activityAt)

  return isActive || isTurn
}

// Session items detection removes: a session continued or archived.
// Commit and dirty items clear only through git (repo checks).
export const autoDone = (items: ReadonlyMap<string, TodoItem>, facts: ReadonlyMap<string, Facts>) => {
  const ids: string[] = []
  for (const item of items.values()) {
    const fact = item.kind === 'session' ? facts.get(item.id.slice(2)) : undefined
    if (fact !== undefined && (fact.isArchived || hasContinued(fact, item.eventAt))) ids.push(item.id)
  }

  return ids
}

export const doneState = (item: { eventAt: number }, now: number): TodoState => ({ doneAt: now, doneFor: item.eventAt })

// The next 08:00 on the local clock, built with the local calendar so a
// daylight-saving change in between does not move it.
export const nextMorning = (now: number) => {
  const morning = new Date(now)
  morning.setHours(MORNING_HOUR, 0, 0, 0)
  if (morning.getTime() <= now) {
    morning.setDate(morning.getDate() + 1)
    morning.setHours(MORNING_HOUR, 0, 0, 0)
  }

  return morning.getTime()
}

// First press: three hours. A second press on the same event: the next 08:00.
export const snoozeState = (item: { eventAt: number }, previous: TodoState | undefined, now: number): TodoState => {
  const isSame = previous?.snoozeFor !== undefined && isSameEvent(previous.snoozeFor, item.eventAt)
  const count = isSame ? previous?.snoozes ?? 0 : 0

  return {
    snoozeUntil: count === 0 ? now + SNOOZE_MS : nextMorning(now),
    snoozes: count + 1,
    snoozeFor: item.eventAt,
  }
}

// Done items older than 7 days go, with their state; so do old orphan states.
// `keep` names ids detection would bring back at once (a session whose finish
// is still current): they stay, so Done stays Done.
export const prune = (
  items: ReadonlyMap<string, TodoItem>,
  states: ReadonlyMap<string, TodoState>,
  now: number,
  keep: ReadonlySet<string>,
) => {
  const dropItems: string[] = []
  const dropStates: string[] = []
  for (const [id, state] of states) {
    if (keep.has(id)) continue
    const isOld = state.doneAt !== undefined && now - state.doneAt > PRUNE_MS
    const item = items.get(id)
    if (item === undefined) {
      const isStale = isOld || (state.doneAt === undefined && (state.snoozeUntil ?? 0) + PRUNE_MS < now)
      if (isStale) dropStates.push(id)
    } else if (isOld && isDone(item, state)) {
      dropItems.push(id)
      dropStates.push(id)
    }
  }

  return { items: dropItems, states: dropStates }
}

