// The plugin's $.store: one key per to-do item (`todo:<id>`) and per user
// action (`todo-state:<id>`), the checks any chat may settle (`pending:<repo>`,
// `dirtycheck:<repo>`), the home chat (`home`) and the last repo scan
// (`scan:repos`). A batch of writes to the first four ends with one bump of
// `todo:rev` (store-sync.ts), so a chat polls that one key and reloads the
// rest only when it moved. A stored value that does not parse is skipped.

import type { EngineInterface } from 'claude-code'

import type { HubRepo } from '../../types'
import { parseDirtyCheck, parsePending } from '../lib/checks'
import type { DirtyCheck, PendingCommit } from '../lib/checks'
import type { Home } from '../lib/home'
import { isObject, num, str } from '../lib/json'
import { parseItem, parseState } from '../lib/todo'
import type { TodoItem, TodoState } from '../lib/todo'

const ITEM = 'todo:'
const STATE = 'todo-state:'
const PENDING = 'pending:'
const CHECK = 'dirtycheck:'
const REV = 'todo:rev'
const HOME = 'home'
const SCAN = 'scan:repos'

export type Loaded = {
  items: Map<string, TodoItem>
  states: Map<string, TodoState>
  pending: Map<string, PendingCommit>
  checks: Map<string, DirtyCheck>
}

// '' when no chat has written yet.
export async function loadRev($: EngineInterface) {
  const value = await $.store.get(REV)

  return isObject(value) ? str(value.rev) ?? '' : ''
}

export const newRev = () => `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`

export async function bumpRev($: EngineInterface, rev: string) {
  await $.store.set(REV, { rev })
}

export async function loadItem($: EngineInterface, id: string) {
  const item = parseItem(await $.store.get(`${ITEM}${id}`))

  return item === null ? null : { ...item, id }
}

export async function loadPending($: EngineInterface, id: string) {
  return parsePending(await $.store.get(`${PENDING}${id}`))
}

export async function loadCheck($: EngineInterface, id: string) {
  return parseDirtyCheck(await $.store.get(`${CHECK}${id}`))
}

export async function loadAll($: EngineInterface): Promise<Loaded> {
  const loaded: Loaded = { items: new Map(), states: new Map(), pending: new Map(), checks: new Map() }
  for (const key of await $.store.keys()) {
    if (key === REV) continue
    if (key.startsWith(ITEM)) {
      const id = key.slice(ITEM.length)
      const item = parseItem(await $.store.get(key))
      if (item !== null) loaded.items.set(id, { ...item, id })
    } else if (key.startsWith(STATE)) {
      const state = parseState(await $.store.get(key))
      if (state !== null) loaded.states.set(key.slice(STATE.length), state)
    } else if (key.startsWith(PENDING)) {
      const pending = parsePending(await $.store.get(key))
      if (pending !== null) loaded.pending.set(key.slice(PENDING.length), pending)
    } else if (key.startsWith(CHECK)) {
      const check = parseDirtyCheck(await $.store.get(key))
      if (check !== null) loaded.checks.set(key.slice(CHECK.length), check)
    }
  }

  return loaded
}

export async function writeItem($: EngineInterface, item: TodoItem) {
  await $.store.set(`${ITEM}${item.id}`, item)
}

export async function writeState($: EngineInterface, id: string, state: TodoState) {
  await $.store.set(`${STATE}${id}`, state)
}

export async function dropItem($: EngineInterface, id: string) {
  await $.store.delete(`${ITEM}${id}`)
  await $.store.delete(`${STATE}${id}`)
}

export async function dropState($: EngineInterface, id: string) {
  await $.store.delete(`${STATE}${id}`)
}

export async function writePending($: EngineInterface, id: string, pending: PendingCommit) {
  await $.store.set(`${PENDING}${id}`, pending)
}

export async function dropPending($: EngineInterface, id: string) {
  await $.store.delete(`${PENDING}${id}`)
}

export async function writeCheck($: EngineInterface, id: string, check: DirtyCheck) {
  await $.store.set(`${CHECK}${id}`, check)
}

export async function dropCheck($: EngineInterface, id: string) {
  await $.store.delete(`${CHECK}${id}`)
}

export async function loadHome($: EngineInterface): Promise<Home | null> {
  const value = await $.store.get(HOME)
  const sessionId = isObject(value) ? str(value.sessionId) : undefined
  if (sessionId === undefined || !isObject(value)) return null

  return { sessionId, hostSessionId: str(value.hostSessionId) ?? null, pid: num(value.pid) ?? null }
}

export async function saveHome($: EngineInterface, home: Home | null, at: number) {
  if (home === null) await $.store.delete(HOME)
  else await $.store.set(HOME, { ...home, at })
}

export type Scan = { at: number; repos: HubRepo[] }

const repoOf = (value: unknown): HubRepo | null => {
  if (!isObject(value)) return null
  const path = str(value.path)
  const name = str(value.name)
  const files = num(value.files)
  const ahead = num(value.ahead)
  if (path === undefined || name === undefined || files === undefined || ahead === undefined) return null

  return {
    path,
    name,
    files,
    newestAt: num(value.newestAt) ?? null,
    ahead,
    hasUpstream: value.hasUpstream === true,
    hasCommits: value.hasCommits !== false,
    isIgnored: value.isIgnored === true,
    hasItem: value.hasItem === true,
  }
}

export async function loadScan($: EngineInterface): Promise<Scan | null> {
  const value = await $.store.get(SCAN)
  if (!isObject(value) || !Array.isArray(value.repos)) return null
  const at = num(value.at)

  return at === undefined ? null : { at, repos: value.repos.flatMap(repo => repoOf(repo) ?? []) }
}

export async function saveScan($: EngineInterface, scan: Scan) {
  await $.store.set(SCAN, scan)
}

