// Checks that outlive the chat that started them, kept in $.store so any chat
// can settle them: a commit still running in the background (`pending:<repo>`)
// and edits still uncommitted after a turn (`dirtycheck:<repo>`).

import type { Head } from './gitfs'
import { isObject, num, pick, str } from './json'
import { repoKey } from './paths'
import { shortId } from './todo'

const MIN = 60 * 1000
export const PENDING_MS = 30 * MIN
export const DIRTY_MS = 10 * MIN
// A dirty check git has not answered for a day after its first miss is dropped.
export const CHECK_GIVE_UP_MS = 24 * 60 * MIN
// After each miss: 1 min, 5 min, 30 min, then every hour.
const BACKOFF_MS = [MIN, 5 * MIN, 30 * MIN, 60 * MIN]
const PATHS_ROOM = 200

// refBefore: the branch HEAD named when the commit started; another branch
// later says nothing about the commit. The small risk that another session
// commits on the same branch in that window is accepted.
export type PendingCommit = { repo: string; headBefore: string | null; refBefore: string | null; startedAt: number }

export type PendingVerdict = 'landed' | 'failed' | 'wait' | 'drop'

export const pendingId = (repo: string) => shortId(repoKey(repo))

// A branch that had a commit and now reads as having none was caught between
// git's writes (or deleted): that says nothing.
export const readableHead = (before: string | null, head: Head | null) =>
  head === null || (before !== null && head.sha === null) ? null : head

// HEAD moved on the same branch: landed. Unchanged for 30 minutes: failed.
// Never readable, or now on another branch: dropped with no verdict.
export const pendingVerdict = (pending: PendingCommit, read: Head | null, now: number): PendingVerdict => {
  const readable = readableHead(pending.headBefore, read)
  const head = readable !== null && readable.ref === pending.refBefore ? readable : null
  if (head !== null && head.sha !== pending.headBefore) return 'landed'
  if (now - pending.startedAt < PENDING_MS) return 'wait'

  return head === null ? 'drop' : 'failed'
}

export const parsePending = (value: unknown): PendingCommit | null => {
  if (!isObject(value)) return null
  const repo = str(value.repo)
  const startedAt = num(value.startedAt)
  const headBefore = value.headBefore === null ? null : str(value.headBefore)
  if (repo === undefined || startedAt === undefined || headBefore === undefined) return null

  return { repo, headBefore, refBefore: str(value.refBefore) ?? null, startedAt }
}

export type DirtyCheck = {
  repo: string
  paths: string[]
  // The latest edit among those paths: what a dirty item is dated from.
  lastEditAt: number
  // When the turn that left them uncommitted ended.
  at: number
  // The session whose turn it was: while it runs again, the check waits.
  owner: string
  // That session's link, for the item.
  link?: string
  // Misses (git gave no answer): how many, since when, and the next try.
  failures?: number
  failedSince?: number
  retryAt?: number
}

export const dirtyCheckId = (repo: string) => shortId(repoKey(repo))

// A new turn's check: the paths joined, the latest edit kept, old misses forgotten.
export const mergeCheck = (stored: DirtyCheck | undefined, next: DirtyCheck): DirtyCheck =>
  stored === undefined ? next : {
    ...next,
    paths: [...new Set([...stored.paths, ...next.paths])].slice(0, PATHS_ROOM),
    lastEditAt: Math.max(stored.lastEditAt, next.lastEditAt),
  }

export const isDue = (check: DirtyCheck, now: number, busy: ReadonlySet<string>) =>
  now - check.at >= DIRTY_MS && now >= (check.retryAt ?? 0) && !busy.has(check.owner)

// git gave no answer: try again later, further apart each time.
export const checkFailed = (check: DirtyCheck, now: number): DirtyCheck => {
  const failures = (check.failures ?? 0) + 1

  return {
    ...check,
    failures,
    failedSince: check.failedSince ?? now,
    retryAt: now + BACKOFF_MS[Math.min(failures, BACKOFF_MS.length) - 1]!,
  }
}

export const isGivenUp = (check: DirtyCheck, now: number) =>
  check.failedSince !== undefined && now - check.failedSince >= CHECK_GIVE_UP_MS

const MISS_FIELDS = ['failures', 'failedSince', 'retryAt'] as const

export const parseDirtyCheck = (value: unknown): DirtyCheck | null => {
  if (!isObject(value) || !Array.isArray(value.paths)) return null
  const repo = str(value.repo)
  const lastEditAt = num(value.lastEditAt)
  const at = num(value.at)
  const owner = str(value.owner)
  const paths = value.paths.filter((path): path is string => typeof path === 'string')
  if (repo === undefined || lastEditAt === undefined || at === undefined || owner === undefined) return null
  const link = str(value.link)

  return { repo, paths, lastEditAt, at, owner, ...(link === undefined ? {} : { link }), ...pick(value, MISS_FIELDS, num) }
}

