// HEAD read from the .git files themselves: no git process, no lock. The
// file reads are passed in, so this stays free of `$`. Anything it cannot
// resolve answers null, and a caller that gets null does not judge.

import { joinPath } from './paths'

export type KindOf = (path: string) => Promise<'file' | 'dir' | null>
export type Reader = (path: string) => Promise<string | null>

export type GitDirs = {
  // The working tree's top folder (the one holding `.git`).
  root: string
  // The repo's own git folder (a worktree's folder under .git/worktrees).
  gitDir: string
  // Where branches and packed-refs live (the main .git for a worktree).
  commonDir: string
}

// sha null: the branch has no commit yet. ref: the branch HEAD names, null
// when HEAD is detached; a commit never changes it, a checkout does.
export type Head = { sha: string | null; ref: string | null }

const SHA = /^[0-9a-f]{40}([0-9a-f]{24})?$/
const REF = /^refs\/[\w.\-/]+$/
const MAX_DEPTH = 64
const MAX_HOPS = 5
const REFTABLE_CONFIG = /^\s*refstorage\s*=\s*reftable\s*$/im
// What HEAD names in a reftable repo.
const REFTABLE_HEAD = 'refs/heads/.invalid'

export const parseGitFile = (text: string | null) => {
  const match = /^gitdir:\s*(.+?)\s*$/m.exec(text ?? '')

  return match === null ? null : match[1]!
}

export const parseHead = (text: string | null): { ref: string } | { sha: string } | null => {
  const line = (text ?? '').trim()
  const ref = /^ref:\s*(\S+)$/.exec(line)?.[1]
  if (ref !== undefined) return REF.test(ref) && !ref.includes('..') ? { ref } : null

  return SHA.test(line) ? { sha: line } : null
}

export const packedRef = (text: string | null, ref: string) => {
  for (const line of (text ?? '').split(/\r?\n/)) {
    if (line.startsWith('#') || line.startsWith('^')) continue
    const [sha, name] = line.trim().split(/\s+/)
    if (name === ref && sha !== undefined && SHA.test(sha)) return sha
  }

  return null
}

const parentOf = (path: string) => path.replace(/[\\/][^\\/]*$/, '')

// Walks up from `dir` to the folder holding `.git` (a folder, or a file
// naming the git folder, as a worktree has).
export async function findGitDirs(dir: string, kindOf: KindOf, read: Reader): Promise<GitDirs | null> {
  let current = dir.replace(/[\\/]+$/, '')
  for (let depth = 0; depth < MAX_DEPTH; depth += 1) {
    const dotGit = joinPath(current, '.git')
    const kind = await kindOf(dotGit)
    let gitDir: string | null = null
    if (kind === 'dir') gitDir = dotGit
    if (kind === 'file') {
      const target = parseGitFile(await read(dotGit))
      if (target === null) return null
      gitDir = joinPath(current, target)
    }
    if (gitDir !== null) {
      const common = (await read(joinPath(gitDir, 'commondir')))?.trim()
      const commonDir = common ? joinPath(gitDir, common) : gitDir
      // Refs kept in a reftable cannot be read as files: unresolvable.
      if ((await kindOf(joinPath(commonDir, 'reftable'))) !== null) return null
      if (REFTABLE_CONFIG.test((await read(joinPath(commonDir, 'config'))) ?? '')) return null

      return { root: joinPath(current, '.'), gitDir, commonDir }
    }
    const parent = parentOf(current)
    if (parent === current || parent === '') return null
    current = parent
  }

  return null
}

export async function readHead(dirs: GitDirs, read: Reader): Promise<Head | null> {
  const head = parseHead(await read(joinPath(dirs.gitDir, 'HEAD')))
  if (head === null) return null
  if ('sha' in head) return { sha: head.sha, ref: null }
  if (head.ref === REFTABLE_HEAD) return null
  let ref = head.ref
  for (let hop = 0; hop < MAX_HOPS; hop += 1) {
    const loose = (await read(joinPath(dirs.commonDir, ref))) ??
      (dirs.gitDir === dirs.commonDir ? null : await read(joinPath(dirs.gitDir, ref)))
    if (loose !== null) {
      const next = parseHead(loose)
      if (next === null) return null
      if ('sha' in next) return { sha: next.sha, ref: head.ref }
      ref = next.ref
      continue
    }
    const packed = packedRef(await read(joinPath(dirs.commonDir, 'packed-refs')), ref)

    return { sha: packed, ref: head.ref }
  }

  return null
}

// One reflog line: `<old> <new> <name> <email> <seconds> <zone>` TAB `<message>`.
export type ReflogEntry = { oldSha: string; newSha: string; at: number; message: string }

const REFLOG_LINE = /^([0-9a-f]{40,64}) ([0-9a-f]{40,64}) .*? (\d+) [+-]\d{4}\t(.*)$/

const REFLOG_LINES = 200

// A branch's recent moves, oldest first: its reflog's last 200 lines.
export const reflogTail = (text: string | null): ReflogEntry[] =>
  (text ?? '').split(/\r?\n/).filter(one => one.trim() !== '').slice(-REFLOG_LINES).flatMap(line => {
    const match = REFLOG_LINE.exec(line)

    return match === null ? [] : [{ oldSha: match[1]!, newSha: match[2]!, at: Number(match[3]) * 1000, message: match[4]! }]
  })

// `commit`, `commit (amend)`, `commit (merge)`, `commit (initial)` and
// `cherry-pick`: a commit made there. A pull, reset, merge, rebase or
// checkout writes other words.
export const isCommitEntry = (message: string) => /^(commit( \((amend|merge|initial)\))?|cherry-pick): /.test(message)

// Whether the branch is there at all (loose or packed).
export async function hasRef(dirs: GitDirs, ref: string, read: Reader) {
  return (await read(joinPath(dirs.commonDir, ref))) !== null ||
    packedRef(await read(joinPath(dirs.commonDir, 'packed-refs')), ref) !== null
}

// Where the reflog of `ref` lives: branches in the common folder, a detached
// HEAD in the repo's own git folder.
export const reflogPath = (dirs: GitDirs, ref: string | null) =>
  ref === null ? joinPath(dirs.gitDir, 'logs/HEAD') : joinPath(dirs.commonDir, `logs/${ref}`)

