// Path helpers for Windows and POSIX spellings alike, with no file system.

export const basename = (path: string | undefined) =>
  (path ?? '').split(/[\\/]/).filter(Boolean).pop() ?? '?'

const DRIVE = /^[A-Za-z]:[\\/]/
const GIT_BASH_DRIVE = /^\/([A-Za-z])(\/|$)/

export const isAbsolute = (path: string) =>
  DRIVE.test(path) || /^[\\/]/.test(path)

const isWindowsStyle = (path: string) => DRIVE.test(path) || /^\\\\/.test(path)

// Git Bash spells C:\x as /c/x.
const fromGitBash = (path: string) =>
  path.replace(GIT_BASH_DRIVE, (_, drive: string, rest: string) => `${drive.toUpperCase()}:${rest || '/'}`)

export const joinPath = (base: string, part: string) => {
  const target = fromGitBash(part)
  const start = isAbsolute(target) ? target : `${base.replace(/[\\/]+$/, '')}/${target}`
  const sep = isWindowsStyle(start) ? '\\' : '/'
  const isUnc = /^[\\/]{2}/.test(start) && sep === '\\'
  const parts: string[] = []
  for (const piece of start.split(/[\\/]+/)) {
    if (piece === '.' || (piece === '' && parts.length > 0)) continue
    if (piece === '..' && parts.length > 1) {
      parts.pop()
      continue
    }
    parts.push(piece)
  }
  const joined = parts.join(sep)

  return isUnc ? `\\\\${joined.replace(/^\\+/, '')}` : joined
}

// One spelling per repo: lower case, forward slashes, no trailing separator.
export const repoKey = (path: string) =>
  fromGitBash(path).replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()

export const sameRepo = (a: string, b: string) => repoKey(a) === repoKey(b)

// `~` and `~/x` start at the home folder, so one setting works on any machine.
export const expandHome = (path: string, home: string | null, sep: string) => {
  if (home === null || !/^~(?:[\\/]|$)/.test(path)) return path

  return `${home.replace(/[\\/]+$/, '')}${path.slice(1).replace(/[\\/]+/g, sep)}`
}

