// What git and the .git files say about a repo's to-do items. A dirty item
// is cleared or cut down only by askDirtyFiles; a commit item only by a
// commit that landed (the guard saw it, or the branch's reflog says so).

import type { EngineInterface } from 'claude-code'

import { hub, isIgnoredRepo, openItems, publish } from './hub'
import { checkFailed, dirtyCheckId, isDue, isGivenUp, pendingId, pendingVerdict } from './lib/checks'
import type { DirtyCheck } from './lib/checks'
import type { Head } from './lib/gitfs'
import { dirtyPaths } from './lib/porcelain'
import { commitItem, commitItemId, commitResolved, dirtyItem, dirtyItemId, dirtyUpdate } from './lib/todo'
import { gitDirtyPaths, pool } from './sources/git'
import { branchExists, findRepo, headOf, movesSince } from './sources/gitfs'
import {
  putCheck, putItem, removeCheck, removeItem, removePending, storedItem, storedPending,
} from './store-sync'
import { addItem } from './todos'

// git for dirty items: at most two at a time.
export const CHECKS_AT_ONCE = 2

const lowered = (paths: readonly string[]) => new Set(paths.map(path => path.toLowerCase()))

const union = (a: readonly string[], b: readonly string[]) =>
  [...new Map([...a, ...b].map(path => [path.toLowerCase(), path])).values()]

// Paths under the repo's real root, relative to it, as git takes them.
const relativeTo = (repo: string, paths: readonly string[]) => {
  const root = repo.replace(/[\\/]+$/, '')
  const prefix = `${root.toLowerCase()}`

  return paths.flatMap(path => (path.toLowerCase().startsWith(prefix) && /^[\\/]./.test(path.slice(root.length))
    ? [path.slice(root.length + 1).replace(/\\/g, '/')]
    : []))
}

// The one way a dirty item is cleared or cut down: git status (porcelain v1,
// every untracked file, read-only, 5 s) of the item's own files and `more`.
// The item keeps exactly its files still uncommitted, and goes when none is.
// Answers the uncommitted paths among those asked, or null when git gave no
// answer (the item then stays as it is). The turn-end check, the 10-minute
// settle, a landed commit and the home scan all ask through here.
export async function askDirtyFiles($: EngineInterface, repo: string, more: readonly string[] = []) {
  const id = dirtyItemId(repo)
  // The repo (or worktree) folder is gone: its files cannot be committed there.
  if (!(await $.fs.exists(repo).catch(() => true))) {
    if ((await storedItem($, id)) !== undefined) await removeItem($, id)
    if (hub.checks.has(dirtyCheckId(repo))) await removeCheck($, dirtyCheckId(repo))

    return []
  }
  const item = await storedItem($, id)
  const paths = union(item?.paths ?? [], more)
  if (paths.length === 0) return []
  const lines = await gitDirtyPaths($, repo, relativeTo(repo, paths))
  if (lines === null) return null
  const dirty = dirtyPaths(repo, lines.join('\n'))
  const isDirty = lowered(dirty)
  const own = item?.paths ?? []
  const still = own.filter(path => isDirty.has(path.toLowerCase()))
  if (item === undefined || still.length === own.length) return dirty
  if (still.length === 0) await removeItem($, id)
  else await putItem($, { ...dirtyItem({ repo, lastEditAt: item.eventAt, paths: still, link: item.link }), createdAt: item.createdAt })

  return dirty
}

// One dirty check, 10 minutes after its turn: the item takes the check's
// files still uncommitted. No answer: try again later, backing off.
async function settleCheck($: EngineInterface, id: string, check: DirtyCheck, at: number) {
  const dirty = await askDirtyFiles($, check.repo, check.paths)
  if (dirty === null) {
    const next = checkFailed(check, at)
    if (isGivenUp(next, at)) await removeCheck($, id)
    else await putCheck($, id, next)

    return
  }
  await removeCheck($, id)
  const checked = lowered(check.paths)
  const left = dirty.filter(path => checked.has(path.toLowerCase()))
  if (left.length === 0 || !hub.options.todo || (await isIgnoredRepo($, check.repo))) return
  const stored = await storedItem($, dirtyItemId(check.repo))
  const next = dirtyItem({
    repo: check.repo,
    lastEditAt: Math.max(check.lastEditAt, stored?.eventAt ?? 0),
    paths: union(stored?.paths ?? [], left),
    link: check.link ?? stored?.link ?? null,
  })
  const item = dirtyUpdate(stored, next)
  if (item !== null) await addItem($, item, at)
}

export async function settleChecks($: EngineInterface, at: number) {
  const due = [...hub.checks].filter(([, check]) => isDue(check, at, hub.busyIds))
  await pool(due.map(([id, check]) => () => settleCheck($, id, check, at)), CHECKS_AT_ONCE)
}

// A commit landed in `repo`: its "did not land" item and pending check go,
// and its dirty item is asked about again (the commit may have taken them).
export async function commitLanded($: EngineInterface, repo: string, at: number) {
  const id = commitItemId(repo)
  if ((await storedItem($, id)) !== undefined) await removeItem($, id)
  if ((await storedPending($, pendingId(repo))) !== undefined) await removePending($, pendingId(repo))
  await askDirtyFiles($, repo)
  await publish($, { todos: openItems(at) })
}

// One item per repo, carrying the latest failed attempt and HEAD at it. An
// older attempt (a background one settled late) never replaces a newer one,
// nor reopens one marked Done.
export async function commitFailed(
  $: EngineInterface, repo: string, eventAt: number, detail: string | null, link: string | null, head: Head | null,
) {
  if (!hub.options.todo || (await isIgnoredRepo($, repo))) return
  const stored = await storedItem($, commitItemId(repo))
  if (stored !== undefined && stored.eventAt > eventAt) return
  const item = commitItem({ repo, at: eventAt, detail, link, head })
  await addItem($, { ...item, createdAt: stored?.createdAt ?? eventAt }, await $.clock.now())
}

// Commits that went to the background: settled from the files by any chat,
// dated from the attempt.
export async function settlePending($: EngineInterface, at: number) {
  for (const [id, pending] of [...hub.pending]) {
    const dirs = await findRepo($, pending.repo, hub.realPaths)
    const head = dirs === null ? null : await headOf($, dirs)
    const verdict = pendingVerdict(pending, head, at)
    if (verdict === 'wait') continue
    await removePending($, id)
    if (verdict === 'landed') await commitLanded($, pending.repo, at)
    if (verdict === 'failed') await commitFailed($, pending.repo, pending.startedAt, 'no new commit after 30 min', null, head)
  }
}

// A commit item whose branch got a commit after the failure (one made by
// hand in a terminal too, or cherry-picked) is resolved; a pull or reset is
// not a commit. A branch that is gone keeps its item (Done clears it).
export async function settleCommitItems($: EngineInterface) {
  for (const item of [...hub.items.values()]) {
    if (item.kind !== 'commit' || item.repo === undefined || item.headSha === undefined) continue
    const dirs = await findRepo($, item.repo, hub.realPaths)
    const ref = item.headRef ?? null
    if (dirs === null || (ref !== null && !(await branchExists($, dirs, ref)))) continue
    if (commitResolved(item, await movesSince($, dirs, ref, item.eventAt))) await removeItem($, item.id)
  }
}

files.hooks/sources/gitfs.ts:
// The repo a folder belongs to, and its HEAD, read from the .git files with
// $.fs alone: no git process, no lock, a few small reads. A repo is known by
// its real path, so one reached through a junction, a symlink or another
// spelling is the same repo.

import type { EngineInterface } from 'claude-code'

import { findGitDirs, hasRef, readHead, reflogPath, reflogTail } from '../lib/gitfs'
import type { GitDirs, Head, ReflogEntry } from '../lib/gitfs'

// Spelling → real path, resolved once per path.
export type RealPaths = Map<string, string>

export async function realPathOf($: EngineInterface, path: string, cache: RealPaths) {
  const known = cache.get(path)
  if (known !== undefined) return known
  const stat = await $.fs.stat(path, { resolve: true }).catch(() => null)
  const real = stat?.realPath ?? path
  cache.set(path, real)

  return real
}

async function readText($: EngineInterface, path: string) {
  const text = await $.fs.read(path).catch(() => null)

  return typeof text === 'string' ? text : null
}

// The repo holding `dir`, its root given as the real path.
export async function findRepo($: EngineInterface, dir: string, cache: RealPaths): Promise<GitDirs | null> {
  const dirs = await findGitDirs(
    dir,
    async path => {
      const stat = await $.fs.stat(path).catch(() => null)

      return stat === null || stat.kind === 'other' ? null : stat.kind
    },
    path => readText($, path),
  ).catch(() => null)

  return dirs === null ? null : { ...dirs, root: await realPathOf($, dirs.root, cache) }
}

export async function headOf($: EngineInterface, dirs: GitDirs): Promise<Head | null> {
  return readHead(dirs, path => readText($, path)).catch(() => null)
}

// $.fs.read refuses files past 4 MiB: such a reflog says nothing.
const REFLOG_ROOM = 4 * 1024 * 1024

// The branch's recent moves, from its reflog's tail; none when the reflog
// has not been written since `since`, or is past the read cap.
export async function movesSince($: EngineInterface, dirs: GitDirs, ref: string | null, since: number): Promise<ReflogEntry[]> {
  const path = reflogPath(dirs, ref)
  const stat = await $.fs.stat(path).catch(() => null)
  if (stat === null || stat.size > REFLOG_ROOM || stat.mtimeMs + 1000 < since) return []

  return reflogTail(await readText($, path))
}

export async function branchExists($: EngineInterface, dirs: GitDirs, ref: string) {
  return hasRef(dirs, ref, path => readText($, path)).catch(() => false)
}

files.hooks/lib/sessions.ts:
// Sorting running personal sessions into waiting / working / unseen for the
// bar, and finding the finishes that become to-do items, from the registry
// (running processes) and the desktop app's records.

import type { HubRow, HubRowState } from '../../types'
import type { Desktop } from './desktop'
import { basename } from './paths'
import { statusKind } from './registry'
import type { Entry } from './registry'

// A finish this close after the focus is the person still looking at it.
export const SLACK_MS = 5000
// A wait older than this is no longer named in the bar: it is a to-do.
export const STALE_MS = 24 * 60 * 60 * 1000
// A status stamped this soon after the process started is the start itself.
export const START_STAMP_MS = 30000

// Whether a registry status stamp ends a turn. Opening a chat whose process
// had stopped makes the app start it, and the start stamps the status with
// no turn. A stamp more than 30 s after the process's own start is a turn's
// end; so is one the desktop's activity time confirms (a real turn moves
// `lastActivityAt` to the stamp). One rule for finishes and for "continued".
export const isTurnEnd = (stampAt: number, startedAt: number | null, activityAt: number | null) =>
  startedAt === null || stampAt > startedAt + START_STAMP_MS ||
  (activityAt !== null && Math.abs(activityAt - stampAt) <= SLACK_MS)

export type SessionInput = {
  // Personal registry entries.
  entries: readonly Entry[]
  // Live process ids; null when unknown (every entry counts as running).
  alive: ReadonlySet<number> | null
  // Desktop records by hostSessionId.
  desktop: ReadonlyMap<string, Desktop>
  now: number
  // This session's own desktop id: never shown.
  selfHost?: string | null
}

// A turn that ended while the user was not watching, or a wait they have not
// answered for a day: a to-do candidate. `key` is the desktop id when known.
export type Finish = {
  key: string
  at: number
  title: string
  detail: string | null
  project: string | null
  link: string | null
}

export type Facts = {
  focusedAt: number | null
  isArchived: boolean
  // When the registry last saw the session change status, and when its
  // process started (a start stamps the status too, with no turn).
  statusAt: number | null
  startedAt: number | null
  // The desktop record's last activity: a turn moves it, a focus does not.
  activityAt: number | null
}

export type Classified = {
  rows: HubRow[]
  finishes: Finish[]
  facts: Map<string, Facts>
}

export const linkOf = (host: string) => `claude://claude.ai/epitaxy/${host}`

// The session on screen at `at`: the one switched to last before it.
const inViewAt = (desktop: ReadonlyMap<string, Desktop>, at: number) => {
  let best: string | null = null
  let bestAt = -1
  for (const [host, record] of desktop) {
    const focused = record.focusedAt
    if (focused !== null && focused <= at && focused > bestAt) {
      best = host
      bestAt = focused
    }
  }

  return best
}

const RANK: Record<HubRowState, number> = { waiting: 0, working: 1, unseen: 2 }

const sinceOf = (entry: Entry) => entry.statusUpdatedAt ?? entry.updatedAt ?? entry.startedAt ?? 0

// The desktop's record first: it is what the app shows.
const folderOf = (entry: Entry | null, record: Desktop | undefined) => record?.cwd ?? entry?.cwd ?? null

const nameOf = (entry: Entry | null, record: Desktop | undefined, key: string) => {
  const folder = folderOf(entry, record)

  return record?.title ?? entry?.name ?? (folder === null ? key : basename(folder))
}

// The summary of the turn that ended at `at`: one of the last answer, written
// at or after the finish. An older one says nothing about this turn.
const summaryAt = (record: Desktop | undefined, at: number) => {
  const summary = record?.summary ?? null
  if (summary === null || !summary.isCurrent) return null

  return record?.writtenAt === null || record?.writtenAt === undefined || record.writtenAt >= at ? summary : null
}

const blockedAsk = (record: Desktop | undefined, at: number) => {
  const summary = summaryAt(record, at)

  return summary?.category === 'blocked' ? summary.needsAction : null
}

// Live entries first, newest first, so a session with two files counts once.
const byFreshness = (entries: readonly Entry[], isAlive: (entry: Entry) => boolean) =>
  [...entries].sort((a, b) => Number(isAlive(b)) - Number(isAlive(a)) || sinceOf(b) - sinceOf(a))

export const classify = (input: SessionInput): Classified => {
  const { alive, desktop, now } = input
  const current = inViewAt(desktop, Number.MAX_SAFE_INTEGER)
  const rows: HubRow[] = []
  const finishes: Finish[] = []
  const facts = new Map<string, Facts>()
  const seen = new Set<string>()

  for (const [host, record] of desktop) {
    facts.set(host, {
      focusedAt: record.focusedAt, isArchived: record.isArchived, statusAt: null, startedAt: null,
      activityAt: record.activityAt,
    })
  }

  const isAlive = (entry: Entry) => alive === null || alive.has(entry.pid)
  const push = (key: string, name: string, state: HubRowState, since: number, host: string | null) =>
    rows.push({ key, name, state, since, link: host === null ? null : linkOf(host) })
  const finish = (key: string, at: number, title: string, detail: string | null, folder: string | null, host: string | null) =>
    finishes.push({ key, at, title, detail, project: folder === null ? null : basename(folder), link: host === null ? null : linkOf(host) })
  if (input.selfHost !== undefined && input.selfHost !== null) seen.add(input.selfHost)

  for (const entry of byFreshness(input.entries, isAlive)) {
    const host = entry.hostSessionId ?? null
    const key = host ?? entry.sessionId
    if (seen.has(key) || !isAlive(entry)) continue
    seen.add(key)
    const record = host === null ? undefined : desktop.get(host)
    if (record?.isArchived === true) continue
    const name = nameOf(entry, record, key)
    const folder = folderOf(entry, record)
    const since = sinceOf(entry)
    const focusedAt = record?.focusedAt ?? 0
    const activityAt = record?.activityAt ?? null
    if (host !== null) {
      facts.set(host, {
        focusedAt: record?.focusedAt ?? null, isArchived: false, statusAt: since, startedAt: entry.startedAt ?? null,
        activityAt,
      })
    }
    const status = statusKind(entry.status)
    if (status === 'working') {
      push(key, name, 'working', since, host)
      continue
    }
    if (status === 'waiting') {
      // A wait not answered for a day is a to-do; the bar no longer names it.
      if (now - since <= STALE_MS) push(key, name, 'waiting', since, host)
      else finish(key, since, name, entry.waitingFor ?? 'waiting', folder, host)
      continue
    }
    const isUnwatched = host !== null && host !== current && isTurnEnd(since, entry.startedAt ?? null, activityAt) &&
      since > focusedAt + SLACK_MS && inViewAt(desktop, since) !== host
    if (!isUnwatched) continue
    const summary = summaryAt(record, since)
    finish(key, since, name, summary?.needsAction ?? summary?.detail ?? null, folder, host)
    push(key, name, 'unseen', since, host)
  }

  // A blocked desktop session whose process is gone, unseen since its last
  // activity: a to-do (the bar names running sessions only).
  for (const [host, record] of desktop) {
    if (seen.has(host) || record.isArchived || host === current) continue
    const activityAt = record.activityAt
    const ask = activityAt === null ? null : blockedAsk(record, activityAt)
    if (ask !== null && activityAt !== null && activityAt > (record.focusedAt ?? 0) + SLACK_MS) {
      finish(host, activityAt, nameOf(null, record, host), ask, record.cwd, host)
    }
  }

  rows.sort((a, b) => RANK[a.state] - RANK[b.state] || a.since - b.since || a.key.localeCompare(b.key))

  return { rows, finishes, facts }
}

