// git status by argv with a timeout, never a shell, and never a write: with
// optional locks off, status does not refresh the index (no index.lock that
// could make another session's commit fail). HEAD is read from files instead
// (sources/gitfs.ts). Each call answers null when git fails.

import type { EngineInterface } from 'claude-code'

// Short: a stuck git (an AV scan, a huge untracked tree) costs a miss, not a wait.
const GIT_MS = 5000
// Global options first: no optional locks, paths printed as they are.
const READ_ONLY = ['--no-optional-locks', '-c', 'core.quotePath=false']

async function git($: EngineInterface, dir: string, args: readonly string[], options: readonly string[] = []) {
  try {
    const ran = await $.process.run(['git', ...READ_ONLY, ...options, '-C', dir, ...args], {
      timeoutMs: GIT_MS,
      env: { GIT_OPTIONAL_LOCKS: '0' },
    })

    return ran.exitCode === 0 ? ran.stdout : null
  } catch {
    return null
  }
}

export async function gitStatus($: EngineInterface, repo: string) {
  return git($, repo, ['status', '--porcelain=v2', '--branch'])
}

// Uncommitted paths among `paths` (relative to the repo's root, taken
// literally: `[id]` is a folder name, not a pattern), or in the whole repo
// when there are too many to name; one per line, every untracked file named.
export async function gitDirtyPaths($: EngineInterface, repo: string, paths: readonly string[]) {
  const named = paths.length > 0 && paths.length <= 100 ? ['--', ...paths] : []
  const text = await git($, repo, ['status', '--porcelain=v1', '--untracked-files=all', ...named], ['--literal-pathspecs'])

  return text === null ? null : text.split(/\r?\n/).filter(line => line.trim() !== '')
}

// Runs `tasks` at most `limit` at a time, in order.
export const pool = async <T,>(tasks: readonly (() => Promise<T>)[], limit: number) => {
  const results: T[] = new Array(tasks.length)
  let next = 0
  const worker = async () => {
    while (next < tasks.length) {
      const index = next
      next += 1
      results[index] = await tasks[index]!()
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, tasks.length) }, worker))

  return results
}

