// The repo scan: the roots' direct subfolders that are git repos, plus repos
// that have an item, each known by its real path (a junction to a repo is the
// same repo). One `git status` per repo, at most four at a time.

import type { EngineInterface } from 'claude-code'

import type { HubRepo } from '../../types'
import { basename, repoKey } from '../lib/paths'
import { parseStatus } from '../lib/porcelain'
import type { StatusFile } from '../lib/porcelain'
import { gitStatus, pool } from './git'
import { realPathOf } from './gitfs'
import type { RealPaths } from './gitfs'

const PARALLEL = 4
const STAT_ROOM = 40

export type ScanArgs = {
  roots: readonly string[]
  // Repos to scan whatever the roots hold (those with a commit or dirty item).
  extra: readonly string[]
  // repoKeys of the real paths of ignored repos and of repos with an item.
  ignored: ReadonlySet<string>
  itemRepos: ReadonlySet<string>
  sep: string
  realPaths: RealPaths
}

async function isRepo($: EngineInterface, dir: string, sep: string) {
  return $.fs.exists(`${dir}${sep}.git`).catch(() => false)
}

async function candidates($: EngineInterface, args: ScanArgs) {
  const found = new Map<string, string>()
  const add = async (path: string) => {
    const real = await realPathOf($, path, args.realPaths)
    if (!found.has(repoKey(real))) found.set(repoKey(real), real)
  }
  for (const root of args.roots) {
    if (await isRepo($, root, args.sep)) await add(root)
    const children = await $.fs.list(root).catch(() => [])
    for (const child of children) {
      if (child.kind !== 'dir' || child.name.startsWith('.')) continue
      const dir = `${root.replace(/[\\/]+$/, '')}${args.sep}${child.name}`
      if (await isRepo($, dir, args.sep)) await add(dir)
    }
  }
  for (const repo of args.extra) await add(repo)

  return [...found.values()]
}

// The newest change: a changed file's mtime (deleted files have none), or
// the last commit or checkout (`.git/logs/HEAD`), whichever is later.
async function newestChange($: EngineInterface, repo: string, files: readonly StatusFile[], sep: string) {
  const paths = files.filter(file => !file.isDeleted).slice(0, STAT_ROOM)
    .map(file => `${repo}${sep}${file.path.replace(/\//g, sep)}`)
  let newest: number | null = null
  for (const path of [...paths, `${repo}${sep}.git${sep}logs${sep}HEAD`]) {
    const stat = await $.fs.stat(path).catch(() => null)
    if (stat !== null && stat.mtimeMs > 0 && (newest === null || stat.mtimeMs > newest)) newest = stat.mtimeMs
  }

  return newest
}

// The scan shows repos; it never judges an item (its listing names an
// untracked folder, not the files in it).
export async function scanRepos($: EngineInterface, args: ScanArgs): Promise<HubRepo[]> {
  const repos = await candidates($, args)
  const results = await pool(repos.map(repo => async (): Promise<HubRepo | null> => {
    const text = await gitStatus($, repo)
    if (text === null) return null
    const status = parseStatus(text)

    return {
      path: repo,
      name: basename(repo),
      files: status.files.length,
      newestAt: await newestChange($, repo, status.files, args.sep),
      ahead: status.ahead,
      hasUpstream: status.hasUpstream,
      hasCommits: status.hasCommits,
      isIgnored: args.ignored.has(repoKey(repo)),
      hasItem: args.itemRepos.has(repoKey(repo)),
    }
  }), PARALLEL)

  return results.filter((repo): repo is HubRepo => repo !== null)
}

