// The 5h and week meters: this session's own reading merged with the file
// every session shares, written back when this one is fresher.

import type { EngineInterface } from 'claude-code'

import type { HubLimit } from '../../types'
import { mergeLimits, parseLimits, toLimits } from '../lib/limits'

export type UsageCache = { shared: HubLimit[]; sharedMtime: number }

export const newUsageCache = (): UsageCache => ({ shared: [], sharedMtime: -1 })

export async function readLimits($: EngineInterface, path: string, cache: UsageCache) {
  const usage = await $.session.usage().catch(() => null)
  const own = toLimits(usage?.rateLimits ?? [])
  const stat = await $.fs.stat(path).catch(() => null)
  if (stat !== null && stat.mtimeMs !== cache.sharedMtime) {
    cache.sharedMtime = stat.mtimeMs
    const text = await $.fs.read(path).catch(() => null)
    cache.shared = parseLimits(typeof text === 'string' ? text : null) ?? cache.shared
  }
  const best = mergeLimits(own, cache.shared)
  if (JSON.stringify(best) !== JSON.stringify(cache.shared)) {
    cache.shared = best
    await $.fs.write(path, JSON.stringify(best)).catch(() => undefined)
  }

  return best
}

