// Short texts for the bar and the to-do list.

export const age = (since: number, at: number) => {
  const minutes = Math.max(0, Math.floor((at - since) / 60000))
  if (minutes < 1) return 'now'
  if (minutes < 60) return `${minutes}m`
  if (minutes < 60 * 24) return `${Math.floor(minutes / 60)}h`

  return `${Math.floor(minutes / (60 * 24))}d`
}

export const until = (ms: number) => {
  const minutes = Math.max(1, Math.ceil(ms / 60000))
  if (minutes < 60) return `${minutes}m`
  if (minutes < 60 * 24) return `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}m`

  return `${Math.floor(minutes / (60 * 24))}d${Math.floor((minutes % (60 * 24)) / 60)}h`
}

export const clip = (text: string, room: number) =>
  text.length <= room ? text : `${text.slice(0, Math.max(1, room - 1))}…`

// One line: collapses runs of white space a summary may hold.
export const oneLine = (text: string) => text.replace(/\s+/g, ' ').trim()

