// Reading `git status --porcelain=v2 --branch` (the scan) and `--porcelain=v1`
// (the dirty checks), and choosing which repos show.

import type { HubRepo } from '../../types'
import { joinPath } from './paths'

// v1 lines are `XY path` or `XY old -> new`: the changed files, as full paths.
export const dirtyPaths = (repo: string, text: string) =>
  text.split(/\r?\n/)
    .filter(line => line.length > 3)
    .map(line => {
      const path = line.slice(3)
      const arrow = path.indexOf(' -> ')

      return joinPath(repo, unquote(arrow < 0 ? path : path.slice(arrow + 4)))
    })

export type StatusFile = { path: string; isDeleted: boolean }

export type RepoStatus = {
  hasCommits: boolean
  hasUpstream: boolean
  ahead: number
  // Changed, conflicted and untracked paths, relative to the repo root.
  files: StatusFile[]
}

// Fields before the path, per entry kind.
const PATH_FIELD: Record<string, number> = { '1': 8, '2': 9, u: 10, '?': 1 }
const LIST_DAYS_MS = 30 * 24 * 60 * 60 * 1000

const unquote = (path: string) =>
  path.startsWith('"') && path.endsWith('"') && path.length >= 2
    ? path.slice(1, -1).replace(/\\(["\\])/g, '$1').replace(/\\t/g, '\t').replace(/\\n/g, '\n')
    : path

const fileOf = (line: string): StatusFile | null => {
  const skip = PATH_FIELD[line[0] ?? '']
  if (skip === undefined) return null
  let at = 0
  for (let field = 0; field < skip; field += 1) {
    at = line.indexOf(' ', at) + 1
    if (at === 0) return null
  }
  // A rename lists `path<TAB>origPath`.
  const path = line.slice(at).split('\t')[0] ?? ''
  // `1 XY ...`: a D on either side is a deletion, a file with no mtime.
  const xy = line[0] === '1' || line[0] === '2' ? line.slice(2, 4) : ''

  return path === '' ? null : { path: unquote(path), isDeleted: xy.includes('D') }
}

export const parseStatus = (text: string): RepoStatus => {
  const status: RepoStatus = { hasCommits: true, hasUpstream: false, ahead: 0, files: [] }
  for (const line of text.split(/\r?\n/)) {
    if (line.startsWith('# branch.oid ')) status.hasCommits = !line.endsWith('(initial)')
    else if (line.startsWith('# branch.upstream ')) status.hasUpstream = true
    else if (line.startsWith('# branch.ab ')) status.ahead = Number(/\+(\d+)/.exec(line)?.[1] ?? 0)
    else {
      const file = fileOf(line)
      if (file !== null) status.files.push(file)
    }
  }

  return status
}

const isRisky = (repo: HubRepo) => repo.files > 0 || repo.ahead > 0 || !repo.hasUpstream || !repo.hasCommits

// Repos with uncommitted, unpushed or never-pushed work, newest change first.
export const riskyRepos = (repos: readonly HubRepo[]) =>
  repos
    .filter(isRisky)
    .sort((a, b) =>
      (b.newestAt ?? Number.MIN_SAFE_INTEGER) - (a.newestAt ?? Number.MIN_SAFE_INTEGER) ||
      a.name.localeCompare(b.name))

// The list's share: what was touched in the last 30 days.
export const listRepos = (repos: readonly HubRepo[], now: number) =>
  riskyRepos(repos).filter(repo => repo.newestAt !== null && now - repo.newestAt <= LIST_DAYS_MS)

