// Defensive readers for undocumented JSON files: a field of the wrong type is
// read as absent, never trusted.

export type Json = Record<string, unknown>

export const parseObject = (text: string | null): Json | null => {
  if (text === null) return null
  try {
    const value: unknown = JSON.parse(text)

    return isObject(value) ? value : null
  } catch {
    return null
  }
}

export const isObject = (value: unknown): value is Json =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

export const str = (value: unknown) => (typeof value === 'string' ? value : undefined)

export const num = (value: unknown) =>
  typeof value === 'number' && Number.isFinite(value) ? value : undefined

// Copies the listed fields that hold the given type.
export const pick = <K extends string, V>(source: Json, keys: readonly K[], read: (value: unknown) => V | undefined) => {
  const out: Partial<Record<K, V>> = {}
  for (const key of keys) {
    const value = read(source[key])
    if (value !== undefined) out[key] = value
  }

  return out
}

