// The desktop app's own record of a session, kept under
// <app>/<account>/<organization>/local_<id>.json. Only the fields below are read.

import { isObject, num, parseObject, str } from './json'
import type { Json } from './json'

export type Summary = {
  // blocked | completed | review_ready
  category: string
  needsAction: string | null
  detail: string | null
  // It summarizes the session's last answer (not an older one).
  isCurrent: boolean
}

export type Desktop = {
  // When the person last switched to it.
  focusedAt: number | null
  title: string | null
  isArchived: boolean
  activityAt: number | null
  cwd: string | null
  summary: Summary | null
  // When the record file was last written (the reader fills it in).
  writtenAt: number | null
}

const text = (value: unknown) => {
  const found = str(value)

  return found === undefined || found.trim() === '' ? null : found
}

// The summary names the answer it summarizes; the record names its last one.
const summaryOf = (raw: Json): Summary | null => {
  const value = raw.postTurnSummary
  if (!isObject(value)) return null
  const category = str(value.status_category)
  if (category === undefined) return null
  const summarizes = str(value.summarizes_uuid) ?? str(raw.postTurnSummaryFor)
  const last = str(raw.lastAssistantUuid)

  return {
    category,
    needsAction: text(value.needs_action),
    detail: text(value.status_detail),
    isCurrent: summarizes === undefined || last === undefined || summarizes === last,
  }
}

export const parseDesktop = (input: string | null): Desktop | null => {
  const raw = parseObject(input)
  if (raw === null) return null

  return {
    focusedAt: num(raw.lastFocusedAt) ?? null,
    title: text(raw.title),
    isArchived: raw.isArchived === true,
    activityAt: num(raw.lastActivityAt) ?? null,
    cwd: text(raw.cwd),
    summary: summaryOf(raw),
    writtenAt: null,
  }
}

