// The bar's look: a mark, a name and an age per session, then the two to-do chips, the 5h and week meters right.

import type { HubLimit, HubRowState } from '../../types'
import { until } from './format'

export const MARK: Record<HubRowState, { glyph: string; color: 'error' | 'warning' | 'success' }> = {
  waiting: { glyph: '●', color: 'error' },
  working: { glyph: '●', color: 'warning' },
  unseen: { glyph: '✓', color: 'success' },
}

export const NAME_ROOM = 22

export type LimitView = { label: string; percent: number; color: 'error' | 'warning' | undefined; reset: string | null }

// Percent coloured at 70 and 90; a window past its reset reads 0, with no reset time.
export const limitView = (limit: HubLimit, now: number): LimitView => {
  const isReset = limit.resetsAt !== null && limit.resetsAt <= now
  const percent = isReset ? 0 : Math.round(limit.percentUsed)

  return {
    label: limit.kind === 'five_hour' ? '5h' : 'week',
    percent,
    color: percent >= 90 ? 'error' : percent >= 70 ? 'warning' : undefined,
    reset: !isReset && limit.resetsAt !== null ? until(limit.resetsAt - now) : null,
  }
}

