// Rate limits are the account's: each session knows what its own last
// response said, and a shared file carries the freshest reading to the rest.

import type { HubLimit } from '../../types'
import { isObject, num } from './json'

const KINDS = ['five_hour', 'seven_day'] as const

type Raw = { readonly kind: string; readonly percentUsed: number; readonly resetsAt?: string }

export const toLimits = (raw: readonly Raw[]): HubLimit[] =>
  KINDS.flatMap(kind => {
    const found = raw.find(limit => limit.kind === kind)
    if (found === undefined) return []
    const resetsAt = found.resetsAt === undefined ? Number.NaN : Date.parse(found.resetsAt)

    return [{ kind, percentUsed: found.percentUsed, resetsAt: Number.isFinite(resetsAt) ? resetsAt : null }]
  })

export const parseLimits = (text: string | null): HubLimit[] | null => {
  if (text === null) return null
  let list: unknown
  try {
    list = JSON.parse(text)
  } catch {
    return null
  }
  if (!Array.isArray(list)) return null

  return list.flatMap(item => {
    if (!isObject(item)) return []
    const kind = KINDS.find(one => one === item.kind)
    const percentUsed = num(item.percentUsed)
    if (kind === undefined || percentUsed === undefined) return []

    return [{ kind, percentUsed, resetsAt: num(item.resetsAt) ?? null }]
  })
}

// The fresher of two readings of one window: the later window, or within one
// window the higher figure (usage only grows until the reset).
const fresher = (a: HubLimit | undefined, b: HubLimit | undefined) => {
  if (a === undefined || b === undefined) return a ?? b
  if ((a.resetsAt ?? 0) !== (b.resetsAt ?? 0)) return (a.resetsAt ?? 0) > (b.resetsAt ?? 0) ? a : b

  return a.percentUsed >= b.percentUsed ? a : b
}

export const mergeLimits = (x: readonly HubLimit[], y: readonly HubLimit[]) =>
  KINDS.flatMap(kind => {
    const best = fresher(x.find(limit => limit.kind === kind), y.find(limit => limit.kind === kind))

    return best === undefined ? [] : [best]
  })

