// The $.state contract of session-hub: what the bar, the to-do list and the
// commands draw from. Written by the plugin's own hooks only.

// waiting: the registry says `waiting`; working: busy, or a background shell
// runs; unseen: a turn ended while the user was not watching it.
export type HubRowState = 'waiting' | 'working' | 'unseen'

// One personal session the bar names.
export type HubRow = {
  // hostSessionId when the desktop knows the session, else the CLI session id.
  key: string
  name: string
  state: HubRowState
  // When it entered this state (ms since the epoch).
  since: number
  // claude://claude.ai/epitaxy/<hostSessionId>, or null.
  link: string | null
}

export type HubTodoKind = 'session' | 'commit' | 'dirty' | 'manual'

// One open to-do item, as the list draws it.
export type HubTodo = {
  id: string
  kind: HubTodoKind
  title: string
  detail: string | null
  project: string | null
  link: string | null
  eventAt: number
  // commit and dirty items: the bar's ⚠ count.
  isRisk: boolean
}

// One repo from the last repo scan.
export type HubRepo = {
  path: string
  name: string
  files: number
  // The newest change: a changed file's mtime, or the last commit.
  newestAt: number | null
  ahead: number
  hasUpstream: boolean
  hasCommits: boolean
  isIgnored: boolean
  hasItem: boolean
}

export type HubLimit = {
  kind: 'five_hour' | 'seven_day'
  percentUsed: number
  resetsAt: number | null
}

declare module 'claude-code' {
  interface PluginState {
    'session-hub': {
      rows: HubRow[]
      now: number
      limits: HubLimit[]
      todos: HubTodo[]
      repos: HubRepo[]
      reposAt: number
      // This chat shows the to-do list above the prompt.
      isHome: boolean
    }
  }
}
